  Skill_117314_AwakerSkillBackgroundStory = {
    Text = "Sie sind schuldig, das fließende schwarze göttliche Blut ist der Beweis. \n Sie sollten gerichtet werden, nur durch die Reinigung ihrer Sünden können sie ins Reine Land gelangen. \n Fällt das Urteil, verkündet ihre Sünden, lasst ihr Blut fließen und lasst die Strafe über sie kommen. \n Dies ist die Macht und Pflicht des Heiligen Sohnes."
  },
  Skill_117314_Desc_0 = {
