  Skill_119762_Desc_3 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Punkte Schaden. Murphy: Wahngeboren erhält <Energy:[Energy:Arg2]> Punkte Aliemus. Ziehe 1 Karte “Tiefseehymne“, die pro Runde maximal 1 Mal aktiviert werden kann."
