  },
  Skill_122485_Desc_15 = {
    Text = "Mouchette erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: „Dramatische Begegnung \"-Schadensinstanzen +2. Das Auslöselimit pro Zug wird auf 5 erhöht. Jedes Mal, wenn „Dramatische Begegnung\" ausgelöst wird, erhält Mouchettes „Schlag \" temporären Gesamtschaden +25%. Erzeuge sofort 2 temporäre „Menschenexplosion\" mit 0 Arithmetica-Kosten."
