  },
  Skill_125370_UnknownName = {
    Text = "Echos des Herrenhauses"
  },
  Skill_125371_AwakerSkillBackgroundStory = {
    Text = "Sie sprechen nie von ihren Ursprüngen, sondern nur von der unbeschreiblichen, immensen Freude über ihre Geburt. \n Dein Bewusstsein wird in Ekstase schmelzen, deine Vergangenheit wird in Ekstase schmelzen, dein Schädel wird in Ekstase schmelzen... dein Gehirn wird in Ekstase schmelzen. \n Eine sanfte und zarte Delikatesse – gelockt von „Sehnsucht“"
  },
  Skill_125371_BattleDesc_0 = {
    Text = "Verursache <Damage:[Damage:Arg1]> Schaden an allen Feinden als garantierten Kritischen Treffer und füge [Arg2]% Gift zu. <ResonanceKeywords:Resonanz 3>: <EmbryoFusionIconKeywords:Embryofusion> +[Arg4]( [Arg5]/3 )."
  },
  Skill_125371_BattleDesc_1 = {
    Text = "Verursache <Damage:[Damage:Arg1]> garantierten Kritischer Treffer-Schaden an allen Feinden und füge [Arg2]% Gift zu, <EmbryoFusionIconKeywords:Embryofusion>+ [Arg6]. <ResonanceKeywords:Resonanz 3>: <EmbryoFusionIconKeywords:Embryofusion> +[Arg4]( [Arg5]/3 )."
  },
  Skill_125371_Desc_0 = {
    Text = "Verursache <Damage:[Damage:Arg1]> garantierten Kritischer Treffer-Schaden an allen Feinden und füge [Arg2]% Gift zu. <ResonanceKeywords:Resonanz 3>: <EmbryoFusionIconKeywords:Embryofusion> +[Arg4]."
  },
  Skill_125371_Desc_1 = {
