  Skill_125376_AwakerSkillBackgroundStory = {
    Text = "Von der Antike bis zur Gegenwart, das Wort Liebe. \n Es bringt die Menschen nur dazu, sich dem Meer der Sünden zuzuwenden und nicht zurückzublicken."
  },
  Skill_125376_Desc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Verringere vorübergehend die <ExhaustionIconKeywords:STR> aller Feinde um [Exhaustion:Arg1].] Erhalte [Arg2] Arithmetica und füge allen Feinden [Poison:Arg3] Schichten <IntoxicationIconKeywords:Gift> zu. Wähle: <WitherKeywords1:Verloben> oder <WitherKeywords2:Fesseln>."
  },
  Skill_125376_Desc_3 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Reduziert vorübergehend die <ExhaustionIconKeywords:STR> aller Feinde um [Exhaustion:Arg1].] Erhalte [Arg2] Arithmetica und füge allen Feinden [Poison:Arg3] Schichten <IntoxicationIconKeywords:Gift> zu. Der Effekt deiner nächsten ausgelösten <ResonanceKeywords:Resonanz> wird verdoppelt. Wähle: <WitherKeywords1:Verloben> oder <WitherKeywords2:Fesseln>."
  },
