  },
  Skill_130943_Desc = {
    Text = "Alle Feinde erhalten 25 <ReinforcePVEKeywords:Burg>, Schlüsselblitz-Grenze und Kosten für Posse-Schlüsselblitz +350. Die erste Posse, die in jeder Runde verwendet wird, wirkt 2 Mal."
