  Skill_132428_AwakerSkillBackgroundStory = {
    Text = "Das Mädchen verlässt widerwillig das bankrotte Aquarium, darf als Lohn ein paar Quallen mitnehmen.\nIhre Lieblingswesen, die Blumen des Meeres.\nMit Pflege füllen sie das ganze Becken!—Das hatte sie sich erhofft"
  },
  Skill_132428_Desc_0 = {
    Text = "Aurita erhält <Energy:[Energy:Arg1]> Punkte Aliemus. <ExaltIconKeywords:Erwecken>: Erhalte 1 Tentakel und lege 2 Karten „Drüsenteilung \" auf die Hand. Wenn Aurita Schaden verursacht, lässt er [Arg2] Tentakel 1 Mal angreifen."
  },
  Skill_132428_Desc_15 = {
    Text = "Aurita erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Erhalte 1 Tentakel und füge 2 „Drüsenspaltung“ der Hand hinzu. Wenn Aurita Schaden verursacht, greifen [Arg2] Tentakel einmal an. Auritas „Schlag“ verursacht Durchdringungsschaden und greift +2 Mal an."
  },
  Skill_132428_EffectNameList = {Text = "Aliemus"},
  Skill_132428_Name = {
    Text = "Test·Erwachen"
  },
  Skill_132429_AwakerSkillBackgroundStory = {
    Text = "Der Ozean ist tief und still, er trägt das Verlangen nach dem Leben und die Angst vor dem Tod. \n Doch es gibt immer wieder Menschen, die den Ozean mit Lachen und Spielereien füllen wollen – wenn Aurita eine solche Einladung aussprechen, kommt immer das Gefühl auf: “Warum nicht mit ihr ein bisschen Spaß haben?“ und lässt das einfache Glück den Brustkorb füllen."
  },
  Skill_132429_Desc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden. Erschöpfen bis zu 10 Karten \"Drüsen-Spaltung\" aus Zieh- und Ablagestapel, jede verursacht zusätzlichen Schaden. Fügt 2 \"Drüsen-Spaltung\" der Hand hinzu. Erhöht den zukünftigen Schaden von \"Aurita\" in diesem Kampf um [Arg2] Punkte"
  },
  Skill_132429_Desc_2 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Punkte <PunctureDamagewords:Durchstechschaden>. Erschöpfen bis zu 10 Karten “Drüsenteilung“ aus Zieh- und Ablagestapel, jede verursacht zusätzlichen Schaden. Fügt 2 “Drüsenteilung“ der Hand hinzu. Erhöht den zukünftigen Schaden von “Aurita“ in diesem Kampf um [Arg2] Punkte."
  },
  Skill_132429_EffectNameList = {
    Text = "Schaden, Folgeschadenssteigerung"
  },
  Skill_132429_Name = {
