  },
  Skill_132433_Desc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Punkte Schaden. Mische [Arg2] Karten“Drüsenvermehrung“in den Ablegestapel. <RippleKeywords:Nachbeben>: Erhalte <Energy:[Energy:Arg3]> Punkte Aelius."
