  Skill_133347_Desc_1 = {
    Text = "<PVPWeaponKeywords:Schicksrad>: Dieses Schicksrad bleibt nach dem Tod erhalten. Beim Tod des Ausrüsters und nach den folgenden [Arg2] Rundenenden im Todeszustand erhalten andere Verbündete <Heal:[Heal:Arg1]> <PVPFeatheredSeedsKeyWords:Gynoecium> und LP."
