  Skill_142695_AwakerSkillBackgroundStory = {
    Text = "Er bewahrte die lebendigsten und liebenswertesten Teile all seiner Liebsten, und er schenkte all seinen Feinden die grausamsten und längsten Qualen.\nIn jeder Nacht des Gelages lachte er und versank in einem Ozean aus leeren Hüllen."
  },
  Skill_142695_BattleDesc = {
    Text = "Entfernt den eigenen <ExhaustionIconKeywords:STR▼>-Zustand. Senkt temporär die <ExhaustionIconKeywords:Stärke> aller Feinde um [Exhaustion:Arg1] Punkte. Verursacht beim Feind mit den niedrigsten LP <RealDamage:Festgesetzten Schaden> in Höhe von [Arg2] % des Tentakelschadens([Arg3]). Wird dieser getötet, wird 1 permanente „Der Knechtgaunt \"-Karte <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> auf die Hand gelegt. Pro Kampf können maximal 3 permanente „Der Knechtgaunt\"-Karten erzeugt werden."
  },
  Skill_142695_Desc = {
    Text = "Entfernt den eigenen <ExhaustionIconKeywords:STR▼>-Zustand. <ExhaustionIconKeywords:STR> aller Feinde –[Exhaustion:Arg8] vorübergehend. Verursacht <RealDamage:Festgesetzter Schaden> in Höhe von [Arg2] % Tentakelschaden am Feind mit den niedrigsten LP. Wird das Ziel dadurch besiegt, wird 1 permanenter „Der Knechtgaunt \"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> auf die Hand generiert. Maximal 3 permanente „Der Knechtgaunts\" pro Kampf generierbar."
  },
  Skill_142695_EffectNameList = {
    Text = "Temporäre STR▼, Tentakel-Schaden-Bonus, Gaunt Level"
  },
  Skill_142695_Name = {
    Text = "Endloses Jagdmahl"
  },
  Skill_142695_OverLimitUtlSkillDesc = {
    Text = "Entfernt den eigenen <ExhaustionIconKeywords:STR▼>-Zustand. Senkt temporär die <ExhaustionIconKeywords:Stärke> aller Feinde um [Exhaustion:Arg1] Punkte. Verursacht beim Feind mit den niedrigsten LP <RealDamage:Festgesetzten Schaden> in Höhe von [Arg6] % des Tentakelschadens([Arg7]). Wird dieser getötet, werden 2 permanente „Der Knechtgaunt \"-Karten <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> auf die Hand gelegt. Pro Kampf können maximal 3 permanente „Der Knechtgaunt\"-Karten erzeugt werden. Reduziert die Arithmetica-Kosten aller „Der Knechtgaunt \"-Karten um 1."
  },
