  Skill_142700_AwakerSkillBackgroundStory = {
    Text = "„Was begehrst du?\"\nStärke, Ordnung, Wiedergefundenes, Blut für Blut...\nEr verfiel in langes, düsteres Schweigen, doch er hatte die Antwort längst gekannt – eine Antwort ohne Lösung.\nEr wollte, dass die Sonne auf- und untergeht, er wollte alles wie gewohnt."
  },
  Skill_142700_BattleDesc_0 = {
    Text = "Pontos erhält <Energy:[Energy:Arg1]> Punkte Aliemus. <ExaltIconKeywords:Erwecken>: Für je 3 „Der Knechtgaunt \"-Karten im Kartenstapel erhält „Unerbittliche Jagd\" 1 zusätzlichen Stapel <BattueKeywords:Rudeljagd>. Für jede gespielte Karte von Pontos erhöht sich der temporäre STR▼-Effekt der nächsten „Unerbittlichen Jagd \" um [Arg3] %. Kann pro Runde maximal 3 Mal ausgelöst werden."
  },
  Skill_142700_BattleDesc_15 = {
    Text = "Pontos erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Für je 2 „Der Knechtgaunts \"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> im Deck erhält „Unerbittliche Jagd\" 1 zusätzlichen Stapel <BattueKeywords:Rudeljagd>. Für jede gespielte Pontos-Karte wird der Temporäre STR▼-Effekt der nächsten „Unerbittlichen Jagd \" um +[Arg3] % erhöht, was bis zu 3 Mal pro Runde ausgelöst werden kann. Erhält beim 1. Spielen von „Schlag\" und „Verteidigung \" pro Runde +<Energy:[Energy:Arg4]> Aliemus."
  },
  Skill_142700_Desc_0 = {
    Text = "Pontos erhält [Arg2] % Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Für je 3 „Der Knechtgaunt \"-Karten im Kartenstapel erhält „Unerbittliche Jagd\" 1 Stapel <BattueKeywords:Rudeljagd>. Für jede gespielte Karte von Pontos erhöht sich der temporäre STR▼-Effekt der nächsten „Unerbittlichen Jagd \" um [Arg3] %. Kann pro Runde maximal 3 Mal ausgelöst werden."
  },
  Skill_142700_Desc_15 = {
    Text = "Pontos erhält [Arg2] % Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Für je 2 „Der Knechtgaunts \"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> im Deck erhält „Unerbittliche Jagd\" 1 Stapel <BattueKeywords:Rudeljagd>. Für jede gespielte Pontos-Karte wird der Temporäre STR▼-Effekt der nächsten „Unerbittlichen Jagd \" um +[Arg3] % erhöht, was bis zu 3 Mal pro Runde ausgelöst werden kann. Erhält beim 1. Spielen von „Schlag\" und „Verteidigung \" pro Runde +<Energy:[Energy:Arg4]> Aliemus."
