  Skill_142846_AwakerSkillBackgroundStory = {
    Text = "Weder das menschliche Ohr noch die gegenwärtige Silberkern Technologie vermögen aus Pontos' Jagdpfeife irgendwelche verwertbaren Informationen zu gewinnen.\nDoch alle von Ebwynnos assimilierten Individuen scheinen sich außerordentlich schnell daran angepasst zu haben, den Befehlen der Pfeife zu folgen."
  },
  Skill_142846_Desc = {
    Text = "Wird diese Fähigkeit im aktuellen Kampf zum ersten Mal eingesetzt, werden 3 verschiedene „Der Knechtgaunt \"-Karten <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> auf die Hand gelegt und <Block:[Block:Arg1]> Punkte Schild erhalten. Für je 4 permanente Knechtgaunt-Karten wird 1 davon zu „Zwiegeborene Gaunts\" aufgewertet. Andernfalls werden 3 „Der Knechtgaunt \"-Karten gezogen."
  },
