  Skill_144438_Desc_1 = {
    Text = "<PVPWeaponKeywords:Schicksrad>: Wenn ein Verbündeter stirbt, erhalte <Energy:[Energy:Arg1]> Aliemus. Wenn ein Verbündeter wiederbelebt wird, erhält er <Energy:[Energy:Arg2]> Aliemus. Der Aliemus-Gewinn-Effekt tritt nur in Kraft, wenn das Aliemus des Ziels nicht voll ist, bis zu [Arg8] Mal. Nachdem der Zähler erschöpft ist, wird dieses Schicksrad zerstört."
  },
  Skill_144438_Name_1 = {
    Text = "Seelensynchronisation"
  },
  Skill_144486_AwakerSkillBackgroundStory = {
    Text = "Die Fee und der Zauberer begegneten sich auf einem öden Fleckchen Erde in einem Winkel einer kleinen Stadt.\nSie winkte lächelnd fein gekleideten fremden Kindern zu, während der Zauberer seinen Blick auf das klingelnde Goldarmband am Handgelenk ihrer Mutter gerichtet hatte.\nIhre Blicke trafen sich in der Luft, und in einem Augenblick verstand jeder die Absicht des anderen.\nIn diesem stillen Wettstreit erwies sich der Zauberer als der Geschicktere und errang mit seiner langjährigen Erfahrung einen knappen Sieg.\nUnd so hob sich der Vorhang für ein brandneues, wunderschönes Unternehmen des Betrugs und der Abzocke."
  },
  Skill_144486_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Erhalte 1 Stapelung <WormGrowth1:Sattheit>. Beim Verursachen von Schaden, füge dem Ziel [<Corrosion:Korrosion>:Arg10] Stapelungen <Corrosion:Korrosion> zu.] Entferne <BurningKeywords2:Verbrennung> von allen Karten auf der Hand. Erhalte <Block:[Block:Arg2]> Schild. Verursache <Damage:[Damage:Arg1]> Schaden [Arg8] Mal an allen Feinden. Jede Stapelung <WormGrowth1:Sattheit> erhöht den Verherrlichungs-Grundschaden und die Schildgenerierung um [Arg6]%. Verbrauche alle <SacrificialMark1:Opfergabe>-Stapelungen; jede Stapelung erhöht die Trefferanzahl der Verherrlichung um 1 und wird in eine gleiche Anzahl von Stapelungen <WormGrowth1:Sattheit> umgewandelt. Aktuelle <WormGrowth1:Sattheit>-Stapelungen: [Arg9]. In diesem Kampf erhaltene Stapelungen: [Arg11]"
  },
