  Skill_144491_AwakerSkillBackgroundStory = {
    Text = "Gier ist die wahre Farbe der menschlichen Natur.\nNiemand kann der Versuchung von Zucker widerstehen, nicht einmal die Feenpatin höchstpersönlich.\nCaraboo grinste breit und entblößte ein Maul voller pechschwarzer, spitzer Zähne."
  },
  Skill_144491_BattleDesc_0 = {
    Text = "Caraboo erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Nach dem Einsatz von „Blutroter Ofen“ kostet der nächste <DerivativeCardKeywords_160:„Wundersamer Segen“> –3 Arithmetica, und jede <FaxianKeywords:Entdecken>-Option wird auf ein Set aufgewertet, das 1 zusätzliche <DerivativeCardKeywords_152:„Segen“>-Karte enthält. Wähle 1 Set aus, um es in deinen Ziehstapel zu mischen."
  },
  Skill_144491_BattleDesc_15 = {
    Text = "Caraboo erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Nach dem Einsatz von „Blutroter Ofen“ kostet der nächste <DerivativeCardKeywords_160:„Wundersamer Segen“> –3 Arithmetica, und jede <FaxianKeywords:Entdecken>-Option wird auf ein Set aufgewertet, das 2 zusätzliche <DerivativeCardKeywords_152:„Segen“>-Karten enthält. Wähle 1 Set aus, um es in deinen Ziehstapel zu mischen. Nach dem Spielen einer „Segen“-Karte: Embryofusion +10. Dieser Fusionseffekt erhöht sich basierend auf deinen verlorenen LP, bis zu +100%."
  },
  Skill_144491_Desc_0 = {
    Text = "Caraboo erhält [Arg2]% Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Nach dem Einsatz von „Blutroter Ofen“ kostet der nächste <DerivativeCardKeywords_160:„Wundersamer Segen“> –3 Arithmetica, und jede <FaxianKeywords:Entdecken>-Option wird auf ein Set aufgewertet, das 1 zusätzliche <DerivativeCardKeywords_152:„Segen“>-Karte enthält. Wähle 1 Set aus, um es in deinen Ziehstapel zu mischen."
  },
  Skill_144491_Desc_15 = {
    Text = "Caraboo erhält [Arg2]% Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Nach dem Einsatz von „Blutroter Ofen“ kostet der nächste <DerivativeCardKeywords_160:„Wundersamer Segen“> –3 Arithmetica, und jede <FaxianKeywords:Entdecken>-Option wird auf ein Set aufgewertet, das 2 zusätzliche <DerivativeCardKeywords_152:„Segen“>-Karten enthält. Wähle 1 Set aus, um es in deinen Ziehstapel zu mischen. Nach dem Spielen einer <Blessing:Segen>-Karte: Embryofusion +10. Dieser Fusionseffekt erhöht sich basierend auf deinen verlorenen LP, bis zu +100%."
  },
