  Skill_145562_Desc_1 = {
    Text = "Wähle einen Feind aus. Beide Seiten <PVPLock:sperren> sich gegenseitig und verursachen <Damage:[Damage:Arg1]> Schaden am Ziel. Stirbt das Ziel unter <PVPLock:Sperre>, kehrt diese Karte in die Hand zurück. <PVPFusion:Fusion>: Schaden+ [Arg2] ."
  },
  Skill_145562_Name_1 = {Text = "Duellpakt"},
  Skill_145612_Desc = {
    Text = "Segen ist eine Buff-Karte mit Arithmetica-Kosten 1, die <RetainIconKeywords:Behalten>, <PrepareKeypvewords:Vorbereiten> und <DepleteIconKeywords:Erschöpfen> besitzt.\nWenn gespielt, erhalte ein <Blessing:Geschenk> mit einem <BlessingNegativeEffect:Preis> und 1 Stapel <SacrificialMark1:Opfergabe>. Es gibt 3 Arten von Segen:\n„Sofortiger Segen“: Verhindert „Verpasste Chance“.\n„Üppiger Segen“: Verhindert „Vergoldete Worte“.\n„Zarter Segen“: Verhindert „Verschleierte Bosheit“."
  },
  Skill_145612_Name = {Text = "Sege"},
  Skill_145664_Desc = {
    Text = "Fügt gemäß Formel [Poison:Arg1] Gift, [Counterattack:Arg2] Konter, [Power:Arg3] Stärke, [Exhaustion:Arg4] Berauben, [TentaclePower:Arg5] Tentakelschaden, [FateCut:Arg6] Endgültiges Urteil, [Corrosion:Arg7] Korrosion hinzu."
  },
  Skill_145664_Name = {
