  },
  Skill_145673_AwakerSkillBackgroundStory = {
    Text = "„Hast du es gesehen? Wie ihr Fleisch unter deiner Klinge aufbrach und in strahlenden Blutblüten erblühte.“\n„Bilde dir nicht ein, dass es aufhört zu existieren, wenn du die Augen schließt, liebes Kind.“\n„Du verstehst es. Du weißt es genau.“\n„Die Fähigkeiten, die du geschärft hast, sind längst in die Farbe des Todes getaucht – sie werden nur das nächste Unheil über andere bringen.“"
  },
  Skill_145673_BattleDesc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Punkte Schaden. Erhält <Energy:[Energy:Arg2]> Punkte Aelius"
