  Skill_145674_AwakerSkillBackgroundStory = {
    Text = "„Hast du es gehört? Wie ihre Schreie in jeden Winkel hallten, doch niemand auch nur den geringsten Schutz für sie aufbot.“\n„Glaube nicht, dass du es ignorieren kannst, indem du dir die Ohren zuhältst, du machtloser Ritter.“\n„Du hast es überlebt. Du hast deine Wahl getroffen.“\n„Als die Flut der Feinde hereinbrach, warfst du deine Rüstung ab und flohst, und überließest das Land, das du am meisten liebtest, der Verwüstung.“"
  },
  Skill_145674_BattleDesc = {
    Text = "Erhalte <Block:[Block:Arg1]> Schild. Erhalte <Energy:[Energy:Arg2]> Wahnsinn"
  },
  Skill_145674_Desc = {
