  },
  Skill_145675_AwakerSkillBackgroundStory = {
    Text = "In Wahrheit hatte Ogier längst vergessen, wie jene Burg wirklich ausgesehen hatte.\nDoch nun konnte er neue Wälle aus den Gebeten schmieden, die tief in seinem Herzen ruhten.\nWenn unter seinem Schutz das Lachen der Menschen noch zu hören wäre und vertraute Blumen wieder über die Felder blühen könnten...\nDann hätte jenes Herz – das längst in etwas anderes verwandelt worden war – noch einen Grund, in dieser Welt zu verweilen."
  },
  Skill_145675_BattleDesc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild, erhalte [Power:Arg2] Punkte <PowerIconKeywords:Stärke>, verbrauche alle <KuangNu:Dunkle Strömung>. Jeder verbrauchte Stapel erhöht den gewährten Schild und die Stärke um 33%. Erhalte 1 Stapel <ShuZui:Selbstschuld>."
  },
  Skill_145675_BattleDesc_3 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild, erhalte [Power:Arg2] Punkte <PowerIconKeywords:Stärke>, verbrauche alle <KuangNu2:Dunkle Strömung>. Jeder verbrauchte Stapel erhöht den gewährten Schild und die Stärke um 50%. Erhalte 1 Stapel <ShuZui:Selbstschuld>."
  },
  Skill_145675_Desc_0 = {
