  Skill_145676_AwakerSkillBackgroundStory = {
    Text = "Als jeder Ritter in den Ritterstand erhoben wurde und seinen Eid ablegte, wurde auch die Waffe an seiner Seite mit Ruhm vergoldet.\nDoch die erste silberne Lanze, die ihm gehört hatte – jene, die mit einer heiligen Mission bedacht worden war – war längst in den sterbenden Gluten der Schlacht geschmolzen.\nDa er jedoch bereits ein Mann war, der mit Sünde beladen war, dachte er, er könnte dieses sündige, trübe Schwarz ebenso gut zu seiner neuen Waffe machen. So, überlegte er, würde es, selbst wenn weiteres Blut es beflecken sollte, jenen, die er einst kannte, keine Schande mehr bereiten."
  },
  Skill_145676_BattleDesc_0 = {
    Text = "Verursache <Damage:[Damage:Arg1]> Schaden, profitiert von [Arg2]% Power-Bonus, erhalte 1 Stapel <KuangNu:Dunklen Surge>."
  },
  Skill_145676_BattleDesc_3 = {
    Text = "Füge <Damage:[Damage:Arg1]> Punkte Schaden zu, profitiere von [Arg2]% Stärkebonus und erhalte 1 Stapel <KuangNu2:Dunkle Strömung>."
  },
  Skill_145676_Desc_0 = {
    Text = "Verursache <Damage:[Damage:Arg1]> Schaden, profitiert von 300 % Power-Bonus, erhalte 1 Stapel <KuangNu:Dunklen Surge>."
