  Skill_145676_EffectNameList = {Text = "Schaden"},
  Skill_145676_Name = {
    Text = "Sündenbefleckte Speerspitze"
  },
  Skill_145676_PropertyNameList = {
    Text = "ANGskraft*Wertsteigerung1"
  },
  Skill_145677_AwakerSkillBackgroundStory = {
    Text = "Einst hatte der Junge versucht, jenen bösen schwarzen Schleim von sich zu reißen – doch egal was er tat, ob er mit den Händen daran zerrte, es mit einer Klinge schnitt oder mit einer stumpfen Waffe darauf einschlug ... der gestaltlose Albtraum ließ sich nicht vertreiben und wurde nur noch dreister.\nAm Ende gestand er sich schließlich ein, dass er und Es längst vollständig zu einem verschmolzen waren, untrennbar voneinander.\nEs war zu seinem Schatten geworden."
  },
  Skill_145677_BattleDesc_0 = {
    Text = "Eidbrecher·Ogier erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Wenn Eidbrecher·Ogier in einer Runde zum ersten Mal mit „Sündenbefleckter Speerspitze“ Schaden verursacht, wende gleiche <Corrosion:Korrosion> an. Die Schild-Verstärkung von „Verteidigung“ erhöht sich um 50 %, ziehe 1 Karte."
  },
  Skill_145677_BattleDesc_15 = {
    Text = "Eidbrecher·Ogier erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Wenn Eidbrecher·Ogier in einer Runde zum ersten Mal mit „Sündenbefleckter Speerspitze“ Schaden verursacht, wende gleiche <Corrosion:Korrosion> an. Der Grundschaden von „Sündenbefleckter Speerspitze“ erhöht sich um 100 %, profitiert zusätzlich von 200 % Power-Bonus. Die Schild-Verstärkung von „Verteidigung“ erhöht sich um 100 %, ziehe 1 Karte."
  },
  Skill_145677_Desc_0 = {
    Text = "Eidbrecher·Ogier erhält [Arg2]% Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Wenn Eidbrecher·Ogier in einer Runde zum ersten Mal mit „Sündenbefleckter Speerspitze“ Schaden verursacht, wende gleiche <Corrosion:Korrosion> an. Die Schild-Verstärkung von „Verteidigung“ erhöht sich um 50 %, ziehe 1 Karte."
  },
  Skill_145677_Desc_15 = {
    Text = "Eidbrecher·Ogier erhält [Arg2]% Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Wenn Eidbrecher·Ogier in einer Runde zum ersten Mal mit „Sündenbefleckter Speerspitze“ Schaden verursacht, wende gleiche <Corrosion:Korrosion> an. Der Grundschaden von „Sündenbefleckter Speerspitze“ erhöht sich um 100 %, profitiert zusätzlich von 200 % Power-Bonus. Die Schild-Verstärkung von „Verteidigung“ erhöht sich um 100 %, ziehe 1 Karte."
  },
  Skill_145677_EffectNameList = {Text = "Aliemus"},
  Skill_145677_Name = {
    Text = "Symbiose mit dem Schwarzen Sumpf"
  },
  Skill_145678_AwakerSkillBackgroundStory = {
    Text = "Bei einer routinemäßigen Inspektion in Misaq untersuchten Forscher gezielt diese formlose Masse aus pechschwarzem Material.\nZu ihrer Überraschung gelang es ihnen tatsächlich, bestimmte materielle Bestandteile daraus zu extrahieren, und sie starteten eifrig ein zweites Experiment – nur um Ergebnisse zu erhalten, die völlig anders waren.\nAls ob es seiner formlosen Natur entspräche, veränderten sich die Bestandteile, aus denen es bestand, von Moment zu Moment, wie ein schwer fassbares Phantom.\nDas, was formlos ist – sein eigentlicher Ursprung ist die Formlosigkeit."
  },
  Skill_145678_Desc = {
    Text = "Senkt vorübergehend die <ExhaustionIconKeywords:Stärke> aller Feinde um [Exhaustion:Arg1], erhält [Power:Arg2] <PowerIconKeywords:Stärke>. Tritt zusätzlich X Mal in Kraft. X beträgt maximal 5."
