  Skill_146012_Desc = {
    Text = "kann nicht ausführen. Auf der Hand:\nAlle Feinde verursachen 25% mehr Schaden an deinem Team.\nAlle Befehlskarten von Lotan: Cetarchon werden zu <DerivativeCardKeywords_154:\"Tödliches Duell\">.\nZu Beginn jedes Zuges, ziehe 1 <DerivativeCardKeywords_154:\"Tödliches Duell\">."
  },
  Skill_146012_Name = {
    Text = "Großschwert·Walfall"
  },
  Skill_146013_AwakerSkillBackgroundStory = {
    Text = "Nur sehr, sehr selten zieht Lotan ihr Schwert zurück.\nDie heterochromen Augen beobachten kühl und ruhig. Das Zurückziehen dient stets nur einem besseren Ausführen des nächsten Hiebs."
  },
  Skill_146013_BattleDesc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Schild. Erhalte <Energy:[Energy:Arg2]> Wahnsinn"
  },
  Skill_146013_BattleDesc_2 = {
    Text = "Erhält <Block:[Block:Arg1]> Punkte Schild. Erhält <Energy:[Energy:Arg2]> Punkte Aliemus. Beim ersten Spielen pro Runde wird 1 „Langklinge·Untergang\" gezogen ( [Arg4]/1 )."
  },
  Skill_146013_Desc_0 = {
    Text = "Erhält <Block:[Block:Arg1]> Punkte Schild. Lotan: Cetarchon erhält <Energy:[Energy:Arg2]> Punkte Aliemus."
