  Skill_146013_Desc_2 = {
    Text = "Erhält <Block:[Block:Arg1]> Punkte Schild. Lotan: Cetarchon erhält <Energy:[Energy:Arg2]> Punkte Aliemus. Beim ersten Spielen pro Runde wird 1 „Langklinge·Untergang\" gezogen."
  },
  Skill_146013_EffectNameList = {
