  Skill_146013_Name = {Text = "VERT"},
  Skill_146013_PropertyNameList = {
    Text = "VERT*GrowValue1,$GrowValue2"
  },
  Skill_146014_AwakerSkillBackgroundStory = {
    Text = "Der schwerste und härteste Schädelknochen des Leviathans wurde zu einer langen Klinge geschliffen – sie nannte sie „Untergang\".\nDas schwere Schwert fegt in einem weiten Bogen hinaus, die Linie der Klinge gleicht der Schwanzflosse eines gewaltigen Wals, und die schweren weißen Knochen zermalmen alles vor ihr.\nTrinke mein Blut, zerfleische mein Leben, sagte Lotan.\nUnd dann lass alle Lebewesen in deiner unaufhaltsamen Spur untergehen."
  },
  Skill_146014_Desc = {
    Text = "Gilt als „Schlag\". Füge allen Feinden <Damage:[Damage:Arg1]> Schaden [Arg3] Mal zu, der einen [Arg2]% Stärke-Bonus genießt. Für jeden in diesem Zug gespielten „Schlag\" kostet die nächste „Langklinge·Untergang\" 1 Arithmetica weniger."
  },
  Skill_146014_EffectNameList = {Text = "Schaden"},
  Skill_146014_Name = {
    Text = "Langklinge·Untergang"
  },
  Skill_146014_PropertyNameList = {
    Text = "ANGskraft*Wertsteigerung1"
  },
  Skill_146015_AwakerSkillBackgroundStory = {
    Text = "Leviathan wird sich stets daran erinnern, wie sie diesen Schwerthieb ausführte.\nIn Seiner Domäne war die selbstüberschätzende Gestalt längst von Wunden übersät. Der menschliche Körper war so schwach – fast ein einziger Atemzug hätte gereicht, um sie nie wieder aufstehen zu lassen. Töricht, anmaßend, bedauernswert – das war Leviathans vollständiges Urteil über sie.\nBevor das Urteil fiel, stand die schwache Gestalt erneut auf. Ihr Lachen ließ Ihn eine Emotion empfinden, die Er noch nie zuvor gekannt hatte.\nEr sah, wie sie mit der zerbrochenen Waffe und dem zerschundenen Körper hoch zu Ihm emporsprang. Er sah die Schwertabsicht, die scheinbar das Sternenmeer zerschneiden konnte, vor Seinen Augen erscheinen.\nIn dem Moment, als das Schwert Ihn durchbohrte, erkannte Leviathan, dass jene Emotion, die Er noch nie erlebt hatte, Angst hieß."
  },
  Skill_146015_Desc_0 = {
    Text = "Verbraucht <DerivativeCardKeywords_153:„Große Klinge: Walfall“> zum Einsetzen. Füge dem Feind mit dem höchsten Schaden <Damage:[Damage:Arg1]> garantierten Kritischen Trefferschaden zu, der von einem [Arg2]% STR-Bonus profitiert. Für jeden +1 Schaden, den <DerivativeCardKeywords_153:„Große Klinge: Walfall“> das Ziel dir gegenüber verursacht, fügt „Mundus-Trennung“ +[Arg4] Schaden zu. <DerivativeCardKeywords_154:>"
  },
  Skill_146015_Desc_3 = {
    Text = "Verbraucht <DerivativeCardKeywords_153:„Große Klinge: Walfall“> zum Einsetzen. Füge dem Feind mit dem höchsten Schaden <Damage:[Damage:Arg1]> garantierten Kritischen Trefferschaden zu, der von einem [Arg2]% STR-Bonus profitiert. Für jeden +1 Schaden, den <DerivativeCardKeywords_153:„Große Klinge: Walfall“> das Ziel dir gegenüber verursacht, fügt „Mundus-Trennung“ +[Arg4] Schaden zu. <DerivativeCardKeywords_154:>"
  },
  Skill_146015_EffectNameList = {
    Text = "Schaden,Stärke-Bonus"
  },
  Skill_146015_Name = {
    Text = "Grenzenspaltende Klinge"
  },
  Skill_146015_OverLimitUtlSkillDesc = {
    Text = "Verbraucht <DerivativeCardKeywords_153:„Große Klinge: Walfall“> zum Einsetzen. Erhalte [Power:Arg3] <PowerIconKeywords:STR>. Füge dem Feind mit dem höchsten Schaden <Damage:[Damage:Arg1]> garantierten Kritischen Trefferschaden zu, der von einem [Arg2]% STR-Bonus profitiert. Für jeden +1 Schaden, den <DerivativeCardKeywords_153:„Große Klinge: Walfall“> das Ziel dir gegenüber verursacht, fügt „Mundus-Trennung“ +[Arg4] Schaden zu. <DerivativeCardKeywords_154:>"
  },
  Skill_146015_PropertyNameList = {
    Text = "ANGskraft*Wertsteigerung1,$Wertsteigerung2％"
  },
  Skill_146016_AwakerSkillBackgroundStory = {
    Text = "Die Gottheit zerriss ihre Seele und ihr Fleisch, in dem Glauben, dies sei das endgültige Urteil über das Chaos.\nDoch die leere Seele hörte nie auf zu suchen, und die abgetrennte Kraft verblasste nie wirklich.\nAls der Knochenpanzer ihren Körper erneut bedeckte, als Leviathans Pulsieren wieder mit ihrem Willen in Resonanz trat – zerbrachen in diesem Moment alle Fesselungen.\nSeele und Fleisch vereinten sich erneut in den Tiefen des Sternenmeers. Die Chaosbestie war nicht länger unvollständig.\nDieses Sternenmeer wird sie erneut willkommen heißen – vollständig und ganz."
  },
  Skill_146016_BattleDesc_0 = {
    Text = "Lotan: Cetarchon erhält <Energy:[Energy:Arg1]> Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Die Befehlskarten von Lotan: Cetarchon verursachen +1 Instanz Schaden.\nZu Beginn des Zuges, wenn <DerivativeCardKeywords_153:„Großschwert·Walfall\"> auf der Hand ist: \nDas erste in diesem Zug gespielte <DerivativeCardKeywords_154:„Tödliche Duell\"> stärkt deine nächste „Grenzenspaltende Klinge\" – für je 1 Aliemus, den es stiehlt, verursacht „Grenzenspaltende Klinge\" +1% Gesamtschaden (max. 90%)."
  },
  Skill_146016_BattleDesc_15 = {
    Text = "Lotan: Cetarchon erhält <Energy:[Energy:Arg1]> Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Die Befehlskarten von Lotan: Cetarchon verursachen +1 Instanz Schaden.\nLotan: Cetarchon erhält durch <DerivativeCardKeywords_154:„Tödliches Duell\"> +50% Aliemus. Zu Beginn des Zuges, wenn <DerivativeCardKeywords_153:„Großschwert·Walfall\"> auf der Hand ist: \nDas erste in diesem Zug gespielte <DerivativeCardKeywords_154:„Tödliche Duell\"> stärkt deine nächste „Grenzenspaltende Klinge\" – für je 1 Aliemus, den es stiehlt, verursacht „Grenzenspaltende Klinge\" +1,5% Gesamtschaden (max. 135%)."
  },
  Skill_146016_Desc_0 = {
    Text = "Lotan: Cetarchon erhält [Arg2]% Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Die Befehlskarten von Lotan: Cetarchon verursachen +1 Instanz Schaden.\nZu Beginn des Zuges, wenn <DerivativeCardKeywords_153:„Großschwert·Walfall\"> auf der Hand ist: \nDas erste in diesem Zug gespielte <DerivativeCardKeywords_154:„Tödliche Duell\"> stärkt deine nächste „Grenzenspaltende Klinge\" – für je 1 Aliemus, den es stiehlt, verursacht „Grenzenspaltende Klinge\" +1% Gesamtschaden (max. 90%)."
  },
  Skill_146016_Desc_15 = {
    Text = "Lotan: Cetarchon erhält [Arg2]% Basis-Aliemus. <ExaltIconKeywords:Erwecken>: Die Befehlskarten von Lotan: Cetarchon verursachen +1 Instanz Schaden.\nLotan: Cetarchon erhält durch <DerivativeCardKeywords_154:„Tödliches Duell\"> +50% Aliemus. Zu Beginn des Zuges, wenn <DerivativeCardKeywords_153:„Großschwert·Walfall\"> auf der Hand ist: \nDas erste in diesem Zug gespielte <DerivativeCardKeywords_154:„Tödliche Duell\"> stärkt deine nächste „Grenzenspaltende Klinge\" – für je 1 Aliemus, den es stiehlt, verursacht „Grenzenspaltende Klinge\" +1,5% Gesamtschaden (max. 135%)."
  },
  Skill_146016_EffectNameList = {Text = "Aliemus"},
  Skill_146016_Name = {
    Text = "Urrückkehr"
  },
  Skill_146017_AwakerSkillBackgroundStory = {
    Text = "Der schärfste Zahn des Leviathans wurde zu einer kurzen Klinge geschliffen – sie nannte sie „Verschlingen\".\nSie hat keinerlei Interesse an Schwachen; die Klingenspitze zeigt stets auf den stärksten Feind. Die Klinge stößt mit extremer Geschwindigkeit vor, und wenn die Nachbilder verblassen, wird auch die Stärke, gewaltig wie ein Sternenmeer, vollständig verschlungen.\nIhre Gier kennt kein Ende – dieser hungrige Blick war seit dem Augenblick ihrer Entstehung auf Lotan gerichtet, und bei jedem Einsatz reißt sie ein Stück Fleisch aus Lotans Körper.\nLotan kümmert es nicht. Sie nährt sie mit Blut und bändigt sie mit Stärke. Sie schwingt sie gegen den stärksten Gegner – den Geschmack der Stärke kosten sie gemeinsam."
  },
  Skill_146017_BattleDesc = {
    Text = "Füge einem zufälligen Feind <Damage:[Damage:Arg1]> Schaden zu, [Arg3] Mal. Erhalte [Power:Arg2] <PowerIconKeywords:Stärke>. Nach dem Spielen wird diese Karte zurück in den Ziehstapel gemischt. Jedes 3. Mal, wenn diese Karte gespielt wird, löst sie 1 zusätzliches Mal aus. Danach wird die nächste in diesem Zug gespielte „Langklinge·Untergang\" mit dieser Karte verschmolzen, um ein <DerivativeCardKeywords_153:„Großschwert·Walfall\"> zu schmieden. ([Arg4]/3) <DerivativeCardKeywords_154:>"
  },
  Skill_146017_Desc = {
    Text = "Gilt als „Schlag\". Füge einem zufälligen Feind <Damage:[Damage:Arg1]> Schaden zu, [Arg3] Mal. Erhalte [Power:Arg2] <PowerIconKeywords:Stärke>. Nach dem Spielen wird diese Karte zurück in den Ziehstapel gemischt. Jedes 3. Mal, wenn diese Karte gespielt wird, löst sie 1 zusätzliches Mal aus. Danach wird die nächste in diesem Zug gespielte „Langklinge·Untergang\" mit dieser Karte verschmolzen, um ein <DerivativeCardKeywords_153:„Großschwert·Walfall\"> zu schmieden. <DerivativeCardKeywords_154:>"
  },
