  Skill_3967_EffectNameList = {Text = "Schaden"},
  Skill_3967_Name = {
    Text = "Auge der Ewigkeit"
  },
  Skill_3967_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Fügt allen Feinden 1 Runde <PetrifactionIconKeywords:Versteinern> hinzu. Wenn das Ziel Versteinerungsresistenz hat, erhöht sich der Gesamtschaden dieses „Auge der Ewigkeit \" um 200%.] Verursacht <Damage:[Damage:Arg1]> Schaden an allen Feinden und fügt [Arg2] Runden <VulnerabilityIconKeywords:Verwundbar> hinzu. Jedes Mal, wenn [Auge der Ewigkeit] freigesetzt wird, erhöht sich der Grundschaden um 50%. Der Gesamtschaden aller Erweckten Körper in dieser Runde erhöht sich um 25%."
  },
  Skill_3967_PropertyNameList = {
