  Skill_3973_AwakerSkillBackgroundStory = {
    Text = "Als sie kurz davor war, von der Stille verschlungen zu werden, schien sie die ertrunkene Zofe zu sehen. \n Die Haut der Zofe war blass, wie eine verwesende Seerose, die im See liegt, und die Wunden an ihrem Hals erstreckten sich entlang der bläulich-weißen Adern bis in die unsichtbare Ferne. \n “Sieh dir deine Katzenauge-Halskette an“, sagte die Leiche, “alles ist zu Asche geworden. Zu Asche geworden...“"
  },
  Skill_3973_Desc = {
    Text = "Heile <Heal:[Heal:Arg1]> Punkte Leben und erhalte <Block:[Block:Arg2]> Punkte Schild. Am Ende der Runde, falls in der Hand, erhöht sich der Arithmetica-Verbrauch um 1, das Heilen von Leben und Schild wird verdoppelt. Höchstens [Arg3] Schichten stapelbar"
