  Skill_3977_AwakerSkillBackgroundStory = {
    Text = "“Komm näher, sei nicht schüchtern, lass den Hutträger dein Lachen und deine Freude kosten.“ \n Meister Casiah tippt auf die Hutkrempe und zaubert mit einem Knall einen großen Haufen Bänder und Karten herbei. \n “Wähle in deinem Herzen deine Karte. Pssst! Sag es niemandem. Meister Casiah wird dir sagen, welche deine Einzige ist.“"
  },
  Skill_3977_Desc_0 = {
    Text = "Wähle eine beliebige Karte aus <DimensionalSpaceIconKeywords:Hyperraum> in deine Hand und verringere die Arithmetica-Kosten um 2. Verursache zufällig <Damage:[Damage:Arg1]> Punkte Schaden [Arg2] Mal. <TransitionIconKeywords:Sprung>: Erhalte [Power:Arg3] Punkte vorübergehende <PowerIconKeywords:Stärke>."
  },
  Skill_3977_Desc_3 = {
    Text = "Gilt als “Schlag“. Wähle eine beliebige Karte aus <DimensionalSpaceIconKeywords:Hyperraum> und lege sie in die Hand, wobei die Arithmetica-Kosten um -2 verringert werden. Verursache zufällig <Damage:[Damage:Arg1]> Punkte Schaden [Arg2] Mal. <TransitionIconKeywords:Sprung>: Füge zusätzlichen 1 Punkt Schaden zu und erhalte [Power:Arg3] Punkte vorübergehende <PowerIconKeywords:Stärke>."
  },
