  },
  Skill_4018_AwakerSkillBackgroundStory = {
    Text = "Schmerz, Schmerz.\nSchwarzer, kalter Schmerz ist eine der wenigen Erinnerungen, die sie hat.\nWenn sie wie ein echter Nautilus eine schöne, harte Schale hätte, würde es dann weniger weh tun?"
  },
  Skill_4018_Desc_0 = {
    Text = "Nautila erhält <Energy:[Energy:Arg1]> Punkte Wahnsinn. <ExaltIconKeywords:Gnosis wecken>: Die von Nautila angewendeten Schilde und <RetaliateIconKeywords:Vergeltung> erhöhen sich um [Arg2] %"
  },
  Skill_4018_Desc_15 = {
    Text = "Nautila erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Rollen-Schild und <RetaliateIconKeywords:Konter>, die von Nautila angewendet werden, +[Arg2]%, und der feste <RetaliateIconKeywords:Konter>, der von allen Erweckten Körpern ausgeteilt wird, +[Arg3]%."
