  Skill_4052_Name = {Text = "Embryo"},
  Skill_4052_tempBattleDesc_1 = {
    Text = "Fleisch-Erwachungskörper verbrauchen diese bei der Verherrlichung, um <DevouredIconKeywords:Verschlingen> auszulösen. Nach dem Spielen: Ein Erwecker erhält <Energy:[Energy:Arg1]> Aliemus und +[Arg2]% kritische Trefferchance in dieser Runde."
  },
  Skill_4052_tempBattleDesc_2 = {
    Text = "Wenn ein Erweckter Körper des Fleisch-Reichs eine Verherrlichung auslöst, kann es verbraucht werden, um den <DevouredIconKeywords:Verschlingen>-Effekt einmal auszulösen. Wähle nach dem Spielen einen Erweckten Körper, der <Energy:[Energy:Arg1]> Aliemus erhält. Wenn ein Erweckter Körper in einer Runde zum ersten Mal „Embryo \" oder „Nachkomme der Reinheit\" verbraucht, erhält er [Arg3] <plural value=\"[Arg3]\" singular=\"Stapelung\" plural=\"Stapelungen\"> <BreedingKeywords1:Ausbreitungsfiesta>."
