  Skill_4054_Name = {Text = "Risswunde"},
  Skill_4055_AwakerSkillBackgroundStory = {
    Text = "Inmitten des endlosen Ozeans schwankt das einsame Schiff mit den Wellen. \n Sie beten, flehen und bitten, in der Hoffnung, dass die weiße Heilige sie vom Meer wegführt und sie wieder auf das Land ihrer Heimat bringt. \n Auf dem Hauptmast hebt das Mädchen im weißen Kleid den Kopf und sieht einen weißen Vogel. \n “Überlasst mir das Steuer, ich werde euch nach Hause bringen.“"
  },
  Skill_4055_BattleDesc_0 = {
    Text = "Vertreibe den Zustand <HeavyInjuryKeywords:Verderben> von dir selbst, heile <Heal:[Heal:Arg1]> Punkte Leben und erhalte 1 Arithmetica. Bei tödlichem Schaden in diesem Kampf einmal wiederbeleben und [Arg2]% (<Heal:[Arg3]>) Leben wiederherstellen, kann nur einmal pro Kampf ausgelöst werden."
  },
  Skill_4055_BattleDesc_3 = {
    Text = "Vertreibe den Zustand <HeavyInjuryKeywords:Verderben> von dir selbst, heile <Heal:[Heal:Arg1]> Punkte Leben und erhalte 1 Arithmetica. Bei tödlichem Schaden in diesem Kampf wiederbeleben, <Arg2>%(<Heal:[Arg3]>) Leben wiederherstellen und allen Erwachten <Energy:[Energy:Arg4]> Punkte Wahnsinn gewähren, nach Auslösung muss eine Pause von 6 Runden eingehalten werden, bevor die Wiederbelebungswirkung erneut angewendet werden kann."
  },
  Skill_4055_Desc_0 = {
