  Skill_4075_AwakerSkillBackgroundStory = {
    Text = "Nymphaea liebt Blumen sehr, außer literarischen Romanen ist dies das einzige, was sie im Krankenbett begleitet. \n Nur seit dem Tod ihrer Eltern hat niemand mehr regelmäßig Trost in Form von Blumen gebracht. \n Der letzte Strauß Lilien hat mit der Zeit allmählich seine Frische verloren. \n Deshalb nahm sie ohne Zögern diesen Strauß zu ihrer eigenen Beerdigung mit. \n Die schwimmenden Fische tanzen im Lichtspiel, Korallen sprießen wie Blätter und strömen mit den Wellen in die Ferne, auf die ihr Blick gerichtet ist."
  },
  Skill_4075_BattleDesc_0 = {
    Text = "Fügt allen Feinden [Poison:Arg1] Schichten <IntoxicationIconKeywords:Gift> hinzu und löst [Arg3]% ihres <IntoxicationIconKeywords:Gift> aus. Erhalte [Power:Arg2] Punkte <PowerIconKeywords:STÄRKE>."
