  Skill_4076_Desc_0 = {
    Text = "Verursache zufällig <Damage:[Damage:Arg1]> Punkte Schaden [Arg2] Mal, dieser Schaden erhält [Arg4]% <RetaliateIconKeywords:Gegenangriff>-Bonus, jeder Angriff verringert das temporäre Ziel um [Exhaustion:Arg3] Punkte <PowerIconKeywords:Stärke>. <TransitionIconKeywords:Sprung>: Verbrauche 5 Schichten <DreamGuide:Traumköder>, wenn erfolgreich, wird der verbrauchte Arithmetica zurückgegeben und zusätzlich 2 Mal Schaden verursacht, andernfalls erhältst du 2 Schichten <DreamGuide:Traumköder>."
  },
  Skill_4076_Desc_1 = {
    Text = "Verursache zufällig <Damage:[Damage:Arg1]> Punkte Schaden [Arg2] Mal, dieser Schaden erhält einen Bonus von [Arg4]% auf <RetaliateIconKeywords:Gegenangriff>, und jeder Angriff verringert vorübergehend das Ziel um [Exhaustion:Arg3] Punkte <PowerIconKeywords:Stärke>. Diese Karte hat eine kritische Trefferquote von 25%. <TransitionIconKeywords:Sprung>: Verbrauche 5 Schichten <DreamGuide:Traumköder>, wenn erfolgreich, wird die verbrauchte Arithmetica zurückgegeben und es werden zusätzlich 2 Mal Schaden verursacht, andernfalls erhalte 2 Schichten <DreamGuide:Traumköder>."
