  Skill_4137_Desc_0 = {
    Text = "Erhalte <Posse:[Arg1]> s-Energie. Wähle 1 Karte aus dem Zieh- oder Ablagestapel und lege sie in deine Hand, setze ihre Arithmetica-Kosten auf 0"
