  Skill_4137_OverLimitUtlSkillDesc_0 = {
    Text = "Erhalte <Posse:[Arg1]> Punkte Keyflare. Wähle 1 Karte aus dem Ziehstapel oder Ablagestapel und lege sie auf die Hand, ihre Arithmetica-Kosten werden auf 0 gesetzt. <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbar> für alle Feinde für 1 Runde, die nächste gespielte Posse wirkt 2 Mal."
  },
  Skill_4137_OverLimitUtlSkillDesc_3 = {
    Text = "Erhalte <Posse:[Arg1]> s-Energie. Wähle 1 Karte aus dem Zieh- oder Ablagestapel und lege sie in deine Hand, setze ihre Arithmetica-Kosten auf 0. Mische 1 <DerivativeCardKeywords_4:“Einblick“> in den Ziehstapel. <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbar> allen Gegnern für 1 Runde, der nächste freigegebene Schlüssel wirkt 2 Mal."
  },
  Skill_4138_AwakerSkillBackgroundStory = {
    Text = "Ramona stellte mit zehn Jahren den Wunsch nach Kampftraining. \n Es ging ihr nicht darum, ein Ritterspiel zu spielen, sondern nachdem sie das Verschwenden und Schwelgen ihres Pflegevaters miterlebt hatte, beschloss das Mädchen, sich auf eine mögliche Pleite vorzubereiten. \n “Die Bezahlung als Königinseeskorte wird wohl höher sein als das Gehalt bei der Polizei, oder?“"
  },
  Skill_4138_Desc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden [Arg2] Mal. Nach dem Ausspielen erhöht sich die Trefferanzahl von \"Schwert der Königin\" um 1, maximal auf [Arg3] Mal. Erhalte [Arg7] temporäre Domänenbeherrschung"
  },
  Skill_4138_Desc_1 = {
    Text = "Füge <Damage:[Damage:Arg1]> Schaden [Arg5] Mal zu und erhalte für jeden Treffer [Power:Arg4] temporäre <PowerIconKeywords:Stärke>. Nach dem Spielen erhöht sich die Trefferanzahl von „Schwert der Königin\" um +1, bis zu einem Maximum von [Arg6] Mal. Erhalte [Arg7] Temporäre Reichsbeherrschung. <RippleKeywords:Nachbeben>: Erhalte Keyflare in Höhe von 300% von Ramonas Keyflare-Regeneration."
  },
  Skill_4138_Desc_3 = {
    Text = "Füge <Damage:[Damage:Arg1]> Schaden [Arg5] Mal zu und erhalte für jeden Treffer [Power:Arg4] temporäre <PowerIconKeywords:Stärke>. Nach dem Spielen erhöht sich die Trefferanzahl von „Schwert der Königin\" um +1, bis zu einem Maximum von [Arg6] Mal. Erhalte [Arg7] Temporäre Reichsbeherrschung. <RippleKeywords:Nachbeben>: Erhalte Keyflare in Höhe von 300% von Ramonas Keyflare-Regeneration."
  },
