  Skill_4152_Desc_0 = {
    Text = "Wähle 1 anderen Erwachten, um ihm <Energy:[Energy:Arg2]> Wahnsinn zu geben. <O07CardKeyWord:Ritual>: Erhöht den Wahnsinn um [Arg4]/[Arg5]/[Arg6]"
