  },
  Skill_4154_AwakerSkillBackgroundStory = {
    Text = "Hör zu, das ist das Läuten der Totenglocke für sich selbst. \n Sie ist nicht der wahnsinnige Suchende, nicht der hilflose Verlorene, sie hat einfach still ihren eigenen Untergang gewählt. \n Die verwelkten Blütenblätter tanzen für ihr Ritual, der rasende Wind weint für ihr Begräbnislied. \n Nach dem durchdringenden Glockenläuten fiel die Welt kurz in eine totenähnliche Stille."
  },
  Skill_4154_Desc_0 = {
    Text = "Fügt allen Feinden [Poison:Arg1] Schichten<IntoxicationIconKeywords:Vergiftung> zu, fügt [Arg2] Runden<WeaknessIconKeywords:Schwäche> und<VulnerabilityIconKeywords:Verwundbarkeit> hinzu"
