  Skill_4284_AwakerSkillBackgroundStory = {
    Text = "Sie sagt immer den Rekruten: Auch wenn man erschöpft ist, auch wenn man schwach ist, darf man die Waffen niemals niederlegen. Lass es zu deinem engsten Gefährten, deinem festesten Schild werden.\nAuf dem Schlachtfeld überlebt nur der, der genügend wachsam ist"
  },
  Skill_4284_BattleDesc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild [Arg2] Mal. Am Ende der Runde, wenn sie auf der Hand sind, füge beim nächsten Spielen zusätzlich 1 Punkt Schild hinzu. Entferne alle Zustände <CardKeyWord:Versiegelt> von Erweckern."
  },
  Skill_4284_BattleDesc_1 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild [Arg2] Mal. Am Ende der Runde, wenn sie auf der Hand sind, erhöht sich der erhaltene Schild um 1 Punkt, wenn sie das nächste Mal gespielt werden. Entferne alle Zustände <CardKeyWord:Versiegelt> von Erweckern. Gilt als “Verteidigung“."
  },
  Skill_4284_Desc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte des Schildes. Am Ende des Zuges, falls auf der Hand, füge beim nächsten Spielen einen zusätzlichen Schild zu. Hebt alle versiegelten Zustände der Erwachter <CardKeyWord:sealed> auf."
