  Skill_4289_Desc = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden [AttackTimes:Arg2] Mal, erhält [Arg3] Punkte Schild. Vor Ende des Spielerzugs erhält man für jede Handkarte zusätzlich [Arg4] Punkte Schild"
  },
  Skill_4289_Name = {Text = "Probe"},
  Skill_4290_AwakerSkillBackgroundStory = {
    Text = "Der Triumphzug ist seit jeher das Bankett der Römer. \n Weiße Tauben, Lorbeerblätter und goldener Konfetti, der durch die Luft wirbelt... all das hat mit dem Krieger zu tun, und doch auch nicht. \n Er und die Kriegsgefangenen aus Gallien, Alexandria und Parthien wurden zusammen an schweren Kreuzen durch die Straßen geführt. \n Das ist das Behalten des Triumphzugs. Der Krieger wird schamlos verspottet, nur weil er als blutiger Komplize des verstorbenen Kaisers angesehen wird. \n Schande, Wut oder Hass? Nein, nichts davon. \n Der Krieger hat keine Emotionen und keine Gedanken. \n Er riecht nur Blut."
  },
  Skill_4290_BattleDesc_0 = {
    Text = "Uvhash erhält <Energy:[Energy:Arg1]> Punkte Wahn. <ExaltIconKeywords:Gnosis wecken>: Uvhash wird nicht von <CardKeyWord:Versiegelung> beeinflusst, die kritische Rate und der kritische Schaden steigen um [Arg2]%, und die Wirkung verdoppelt sich, wenn das Leben unter 25% fällt"
