  Skill_4329_BattleDesc_0 = {
    Text = "Erhalte <Block:[Block:Arg3]> Punkte Schild, lege alle Karten auf der Hand ab. <TransitionIconKeywords:Sprung>: Lege keine Karten mehr ab, erhalte <Block:[Block:Arg4]> Punkte Schild und ziehe 1 Karte."
