  Skill_4372_Name = {Text = "Todeskampf"},
  Skill_4373_AwakerSkillBackgroundStory = {
    Text = "Ihre Vorderflosse kann den Kurs spalten, die Schwanzflosse reicht aus, um einen Hafen zu zerschlagen.\nNachdem niemand mehr kämpfen konnte, schlief der Wal im Chaos ein und überließ den Planeten den neuen Lebewesen"
  },
  Skill_4373_BattleDesc_0 = {
    Text = "Vertreibt eigenen <WeaknessIconKeywords:Schwäche>-Status. Verursacht <Damage:[Damage:Arg1]> Schaden an allen Feinden [Arg3] Mal. Für jede gespielte „Schlag“-Karte in diesem Kampf +[Arg2] Schaden."
  },
  Skill_4373_BattleDesc_3 = {
    Text = "Vertreibt eigenen <WeaknessIconKeywords:Schwäche>-Status. Verursacht <Damage:[Damage:Arg1]> Schaden an allen Feinden [Arg3] Mal. Für jede gespielte “Schlag“-Karte in diesem Kampf +[Arg2] Schaden. Füge 2 “Schlag“-Karten mit <DepleteIconKeywords:Verbrauch> und <NothingnessIconKeywords:Nichtigkeit> zur Hand hinzu."
  },
  Skill_4373_Desc_0 = {
    Text = "Vertreibt eigenen <WeaknessIconKeywords:Schwäche>-Zustand. Verursacht <Damage:[Damage:Arg1]> Schaden an allen Feinden. Für jede gespielte „Schlag“-Karte in diesem Kampf +[Arg2] Schaden"
  },
  Skill_4373_Desc_15 = {
    Text = "Dispelliere deinen eigenen <WeaknessIconKeywords:Weakness> Zustand. Füge allen Feinden <Damage:[Damage:Arg1]> Schaden [Arg3] Mal zu. Für jeden \"Schlag\", der in diesem Kampf gespielt wird, erhöht sich der Schaden um [Arg2]. Lege 2 \"Schläge\" mit <DepleteIconKeywords:Exhaust> und <NothingnessIconKeywords:Illusion> auf die Hand."
  },
  Skill_4373_Desc_3 = {
    Text = "Vertreibt eigenen <WeaknessIconKeywords:Schwäche>-Zustand. Verursacht <Damage:[Damage:Arg1]> Schaden an allen Feinden [Arg3] Mal. Für jede gespielte “Schlag“-Karte in diesem Kampf +[Arg2] Schaden. Füge 2 “Schlag“-Karten mit <DepleteIconKeywords:Verbrauch> und <NothingnessIconKeywords:Nichtigkeit> zur Hand hinzu."
  },
  Skill_4373_EffectNameList = {
