  Skill_4373_Name = {
    Text = "Chaosbestie"
  },
  Skill_4373_OverLimitUtlSkillDesc_0 = {
    Text = "Entferne den eigenen <WeaknessIconKeywords:Symptom: Schwäche>-Zustand. Füge allen Feinden <Damage:[Damage:Arg1]> SCH zu. Für jeden in diesem Kampf gespielten „Schlag“ erhöht sich der Schaden um [Arg2]. Füge allen Feinden zusätzlich einmal Festgesetzten Schaden in Höhe von 15% der maximalen LP des Ziels zu. Der Grundschaden der „Chaosbestie“ erhöht sich für diesen Kampf um +100%."
  },
  Skill_4373_OverLimitUtlSkillDesc_3 = {
    Text = "Entferne den eigenen <WeaknessIconKeywords:Symptom: Schwäche>-Zustand. Füge allen Feinden <Damage:[Damage:Arg1]> SCH [Arg3] <plural value=\"[Arg3]\" singular=\"Mal\" plural=\"Mal\"> zu. Für jeden in diesem Kampf gespielten „Schlag“ erhöht sich der Schaden um [Arg2]. Füge deiner Hand 2 „Schlag“-Karten mit <DepleteIconKeywords:Erschöpfen> und <NothingnessIconKeywords:Nichtigkeit> hinzu. Füge allen Feinden einmalig zusätzlich 15% der maximalen LP des Ziels als Festgesetzten Schaden zu. Erhöhe den Grundschaden der „Chaosbestie“ für diesen Kampf um 100%."
  },
  Skill_4373_PropertyNameList = {
    Text = "ANGskraft*Wertsteigerung1,ANGskraft*Wertsteigerung2"
  },
  Skill_4374_Desc = {
    Text = "Eine leichte Verletzung, nichts Ernstes. Erleide <Damage:[Arg1]> SCH und ziehe [Arg3] <plural value=\"[Arg3]\" singular=\"Karte\" plural=\"Karten\">."
  },
  Skill_4374_Name = {Text = "Wunde"},
  Skill_4375_AwakerSkillBackgroundStory = {
    Text = "Schritt für Schritt trat sie langsam ins Meer. \nDas nächtliche Meer, das gerade ihre Haut berührte, schien noch etwas kühl, doch in diesem Moment war es so warm wie die Umarmung eines Menschen. \nDas Meer nahm mich auf, solche Gedanken schwebten leise in Nymphaeas Kopf. \nPlötzlich sah sie das Lächeln ihrer Eltern. In der Tiefe des Meeres muss es sicherlich das Glück der Familie geben."
  },
  Skill_4375_Desc_0 = {
    Text = "Nymphaea erhält <Energy:[Energy:Arg1]> Punkte Aliemus. <ExaltIconKeywords:Gnosis wecken>: Nachdem Nymphaea eine Karte gespielt hat, erhält sie <Energy:[Energy:Arg2]> Punkte Aliemus."
