  Skill_4381_Desc_15 = {
    Text = "Caecus erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Erhält 1 Tentakel. Für jede Karte, die Caecus spielt, werden <Heal:[Heal:Arg2]> LP wiederhergestellt und [Counterattack:Arg3] <plural value=\"[Counterattack:Arg3]\" singular=\"Stapelung\" plural=\"Stapelungen\"> <RetaliateIconKeywords:Konter> erhalten. 1 Tentakel führt einen Angriff aus und erhält Konter in Höhe von [Arg4]% des verursachten Schadens."
  },
