  Skill_4383_Name = {Text = "Flackern"},
  Skill_4384_AwakerSkillBackgroundStory = {
    Text = "Je mehr Enthaltsamkeit und Unterdrückung herrscht, desto erstaunlicher ist die Kontrolle des Mädchens. \n Das laute Peitschenknallen entspricht süßen Liebesworten, das heiße Wachs ersetzt heiße Küsse, die straffen Seile sind sorgfältige Zuwendung, und die geschwollenen Narben sind der Beweis für die Liebe. \n In jener honigfarbenen, tragischen Illusion ertönt das silberne Lachen des Mädchens."
  },
  Skill_4384_Desc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden an allen Feinden, jeder Schicht <RetaliateIconKeywords:Gegenangriff> erhöht den Schaden um [Arg2] Punkte. Wenn nur 1 Feind vorhanden ist, verursacht es 2 Mal Schaden. Erhält [Power:Arg3] Punkte <PowerIconKeywords:Stärke>."
  },
  Skill_4384_Desc_3 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden an allen Feinden, jede Schicht <RetaliateIconKeywords:Gegenangriff> erhöht den Schaden um [Arg2] Punkte. Wenn nur ein Gegner vorhanden ist, verursacht es 2 Mal Schaden. Erhält [Power:Arg3] Punkte <PowerIconKeywords:Kraft>. Erhält [Counterattack:Arg4] Schichten <RetaliateIconKeywords:Gegenangriff>."
  },
