  Skill_4403_AwakerSkillBackgroundStory = {
    Text = "Unzählige Zahnräder überlappen sich und treiben sich gegenseitig an, wodurch der porzellanartigen Hülle die Fähigkeit verliehen wird, Leben zu imitieren.\nDies ist ihr stolzestes Werk, ein unvergleichliches, raffiniertes Instrument.\nErica hätte niemals gedacht, dass diese Automatons, die ihren Namen trägt, zu ihrem zweiten Leben werden würde."
  },
  Skill_4403_Desc_0 = {
    Text = "Erica erhält <Energy:[Energy:Arg1]> Punkte Wahnsinn. <ExaltIconKeywords:Gnosis wecken>: Wenn Erica Schaden verursacht, erhält sie [Power:Arg2] Punkte vorübergehende <PowerIconKeywords:Macht>; Wenn Erica einen Schild anwendet, erhält sie [Arg3] Punkte vorübergehende <AlertIconKeywords:Alarm>"
  },
  Skill_4403_Desc_15 = {
