  Skill_4407_AwakerSkillBackgroundStory = {
    Text = "Ihre Haut ist grün, die verfaulten Blutgefäße winden sich ständig und spiralförmig. \n Ihre Schulter scheint etwas auszubrüten – schwarze Flüssigkeit fließt an ihrem Arm entlang und breitet sich auf dem Operationstisch aus. \n Neugeborenes Fleisch blüht aus der Wunde, drängt sich vor und ist sanft und lautlos. \n Das schwache Mädchen lächelt. \n “Endlich wiedersehen, @2.“"
  },
  Skill_4407_Desc_0 = {
    Text = "Verursacht zufällig <Damage:[Damage:Arg1]> Punkte Schaden [Arg2] Mal. Bis zum Beginn der nächsten Runde, erhält man für jeden Verlust von 2 Lebenspunkten zu Beginn der nächsten Runde 1 Schildpunkt."
