  Skill_4413_Desc_0 = {
    Text = "Elva erhält <Energy:[Energy:Arg1]> Punkte Wahnsinn. <ExaltIconKeywords:Gnosis wecken>: Erhält [Arg2] Punkte <AlertIconKeywords:Alarm>. Der durch Elvas Befehlskarten verursachte Schaden erhöht sich mit dem aktuellen Schild, wobei jeder Punkte des Schildes den Schaden um 1 erhöht"
