  Skill_4574_Name = {Text = "Speerstoß"},
  Skill_4575_AwakerSkillBackgroundStory = {
    Text = "Es ist eine antike Ruine aus Korallen. \n Zunächst war es nur ein schimmernder weißer Glanz, der im Meer schwebte. \n Später wuchsen hohe Stufen, verzerrte Reliefs und hohe Säulen... \n Bumm! Als alles plötzlich zum Stillstand kam, hob die verlorene Kunst endlich den Schleier am Meeresgrund. \n Sie musste zu dem Ort der Kunst reisen."
  },
  Skill_4575_BattleDesc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild. Verursacht <Damage:[Damage:Arg2]> Schaden bei allen Feinden, jeder Schildpunkt erhöht den Schaden um [Arg3] Punkte, diese Fähigkeit erhält zusätzlich [Arg4]% kritische Rate und kritischen Schadenbonus. Im Anführer Kampf verursacht diese Fähigkeit zusätzlich 1 Mal Schaden."
  },
  Skill_4575_BattleDesc_3 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild. Füge allen Feinden <Damage:[Damage:Arg2]> Schaden zu, jeder Schildpunkt erhöht den Schaden um [Arg3] Punkte, diese Fähigkeit erhält zusätzlich [Arg4]% kritische Rate und kritischen Schadenbonus. Im Anführer Kampf fügt diese Fähigkeit zusätzlich 1 Mal Schaden zu."
  },
  Skill_4575_Desc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild. Füge allen Feinden <Damage:[Damage:Arg2]> Schaden zu, jeder Punkt Schild erhöht den Schaden um [Arg3] Punkte, diese Fähigkeit profitiert zusätzlich von [Arg4]% kritischer Rate und kritischem Schaden. Im Anführer Kampf fügt diese Fähigkeit zusätzlich 1 Mal Schaden zu."
  },
  Skill_4575_Desc_3 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild. Füge allen Feinden <Damage:[Damage:Arg2]> Schaden zu, wobei jeder Schildpunkt den Schaden um [Arg3] Punkte erhöht. Diese Fähigkeit profitiert zusätzlich von [Arg4]% kritischer Rate und kritischem Schadenbonus. Im Anführer Kampf verursacht diese Fähigkeit zusätzlich 1 Mal Schaden."
  },
  Skill_4575_EffectNameList_0 = {
    Text = "Schild, Schaden"
  },
  Skill_4575_Name = {
    Text = "Die verlorene Kunst"
  },
  Skill_4575_OverLimitUtlSkillDesc_0 = {
    Text = "Erhalte <Block:[Block:Arg5]> Punkte Schild. Verursache <Damage:[Damage:Arg2]> Schaden bei allen Gegnern; pro Schild-Punkt erhöht sich der Schaden um [Arg3] Punkte. Diese Fähigkeit erhält zusätzlich [Arg4]% kritische Rate und kritischen Schadenbonus. Im Anführer Kampf verursacht diese Fähigkeit zusätzlich 1 Mal Schaden. Der Schaden von “Die verlorene Kunst“ und “Grundschlag“ im Kampf erhöht sich zusätzlich um 100 % durch den Schildbonus."
  },
  Skill_4575_OverLimitUtlSkillDesc_3 = {
    Text = "Erhalte <Block:[Block:Arg5]> Punkte Schild. Verursache <Damage:[Damage:Arg2]> Schaden bei allen Gegnern; pro Schild-Punkt erhöht sich der Schaden um [Arg3] Punkte. Diese Fähigkeit erhält zusätzlich [Arg4]% kritische Rate und kritischen Schadenbonus. Im Anführer Kampf verursacht diese Fähigkeit zusätzlich 1 Mal Schaden. Der Schaden von “Die verlorene Kunst“ und “Grundschlag“ im Kampf erhöht sich zusätzlich um 100 % durch den Schildbonus."
  },
