  Skill_4579_AwakerSkillBackgroundStory = {
    Text = "Der Zauberer sagte: „Die Anzahl der Heiden ist groß, \n wir Levante scheinen schwach zu sein. \n Bruder Uvhash, blase in dein Horn, \n kämpfe wie ein Verrückter.“ \n Der Krieger antwortete: „Hier gibt es keine Heiden. \n Ihr werdet alle von mir getötet, die Verstorbenen unterscheiden sich nicht in Rasse oder Glauben. \n Zu diesem Zeitpunkt werden die Leichname das Tal bedecken, die Gipfel übersäen, \n und das wird mein Opfer für die Hymne aus Blut und Sand sein.“"
  },
  Skill_4579_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Der Schaden von “Hymne aus Blut und Sand“, der in diesem Kampf freigesetzt wird, erhöht sich um [Arg4] Punkte, der Kraftmultiplikator erhöht sich um [Arg3]-fach.] Füge allen Feinden <Damage:[Damage:Arg1]> Punkte Schaden zu. <PowerIconKeywords:Stärke> wirkt [Arg2]-fach auf “Hymne aus Blut und Sand“. Uvhash erhält <Energy:[Energy:Arg5]> Punkte Aelius."
  },
  Skill_4579_Desc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Der Schaden von im weiteren Verlauf des Kampfes freigesetzten „Hymne aus Blut und Sand \" erhöht sich um [Arg4] Punkte, der Kraftmultiplikator erhöht sich um [Arg3] -fach.] Verursacht <Damage:[Damage:Arg1]> Punkte Schaden an allen Feinden. <PowerIconKeywords:Stärke> entfaltet eine [Arg2] -fache Wirkung auf „Hymne aus Blut und Sand\". Erhält Aliemus in Höhe des 2-fachen von Uvhashs Wutregeneration."
  },
  Skill_4579_EffectNameList = {
    Text = "Schaden, Schadenssteigerung"
  },
  Skill_4579_Name = {
    Text = "Hymne aus Blut und Sand"
  },
  Skill_4579_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Der Schaden von “Hymne aus Blut und Sand“, der in diesem Kampf freigesetzt wird, erhöht sich um [Arg4] Punkte, der Multiplikator für die Stärke steigt um [Arg3]-fach.] Verursacht <Damage:[Damage:Arg1]> Punkte Schaden bei allen Feinden. <PowerIconKeywords:Stärke> entfaltet [Arg2]-fache Wirkung auf “Hymne aus Blut und Sand“. Uvhash erhält <Energy:[Energy:Arg5]> Punkte Aelius. Fülle die Handkarte mit der zusätzlichen Nichtigkeit und den Kosten von “Kreisch, Blut!“. In dieser Runde erhöht sich die Schadensanzahl von Uvhash um 1."
  },
  Skill_4579_PropertyNameList = {
    Text = "ANGskraft*Wertsteigerung1,ANGskraft*Wertsteigerung2"
