  },
  Skill_4581_AwakerSkillBackgroundStory = {
    Text = "Unter der Kirche gibt es einen versteckten Raum.\n\nDer Bischof kniet vor der Steinplatte und rezitiert das Passwort, das aus der Zeit der Schöpfung übrig geblieben ist.\n\nDie von der Zeit vergessenen Runen strahlen ein antwortendes Licht aus und erscheinen in Übereinstimmung mit dem Willen des Bischofs als gewaltige Erscheinung, um denjenigen, die im Glanz stehen, den “Segen“ des Schöpfers zu gewähren."
  },
  Skill_4581_Desc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Erhalte [Power:Arg1] Punkte vorübergehende <PowerIconKeywords:Stärke>, temporäre kritische Trefferquote +[Arg4]%.] Erhalte <Block:[Block:Arg2]> Punkte Schild. <VulnerabilityIconKeywords:Verwundbar> alle Feinde für 1 Runde. Bis zum Beginn der nächsten Runde wird beim Erleiden von Schaden [Arg3]% des Schadens in die Rückgewinnung des Blutroten Ofens umgewandelt."
  },
  Skill_4581_Desc_3 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Erhält [Power:Arg1] vorübergehende <PowerIconKeywords:Macht>, Temporäre Kritische Trefferquote +[Arg4]%.] Erhalte <Block:[Block:Arg2]> Rollen-Schild. <VulnerabilityIconKeywords:Verwundbar> für alle Feinde 1 Runde. Bis zum Beginn der nächsten Runde wird bei erlittenem Schaden [Arg3]% in Blutroter Ofen Heilung umgewandelt. Salvador erhält [Arg5]% Temporären Kritischen Schaden."
  },
  Skill_4581_EffectNameList = {
    Text = "Vorübergehende Macht, Schild, Purpurner Ofen Umwandlungsmenge"
  },
  Skill_4581_Name = {
    Text = "Segen des Schöpfers"
  },
  Skill_4581_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Erhalte [Power:Arg1] Punkte temporäre <PowerIconKeywords:Stärke>, Temporäre Kritische Trefferquote +[Arg4] %.] Erhalte <Block:[Block:Arg2]> Punkte Schild. <VulnerabilityIconKeywords:Verwundbar> für alle Feinde für 1 Runde. Bis zum Beginn der nächsten Runde wird beim Erleiden eines Angriffs [Arg6] % des Schadens in Heilung für den Blutroter Ofen umgewandelt. Salvadors „Basisschlag \" und „Ende des Leidens\" profitieren zusätzlich von 100% Stärkebonus. In dieser Erkundung wird die Obergrenze des Blutroter Ofens um 2% der maximalen LP erhöht, maximal um 10%."
  },
  Skill_4581_OverLimitUtlSkillDesc_3 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Erhalte [Power:Arg1] Punkte temporäre <PowerIconKeywords:Macht>, temporäre kritische Trefferquote +[Arg4]%.] Erhalte <Block:[Block:Arg2]> Punkte Schild. <VulnerabilityIconKeywords:Verwundbar> alle Feinde 1 Runde. Bis zum Beginn der nächsten Runde wird [Arg6]% des erlittenen Schadens in die Rückgewinnung des Blutroten Ofens umgewandelt. Salvador erhält [Arg5]% temporären kritischen Schaden. Salvador's “Basis-Schlag“ und “Ende des Leidens“ erhalten zusätzlich 100% Stärke-Bonus. Das Limit des Blutroten Ofens wird in dieser Erkundung um 2% der maximalen Lebenspunkte erhöht, maximal um 10%."
  },
