  Skill_4662_AwakerSkillBackgroundStory = {
    Text = "Die Menschen bewundern ihre Schönheit und beneiden ihren Charme, aber niemand wird eine Knospe ernst nehmen. \n Die in der Wildnis schwankende Knospe wird willkürlich in ihrer Zukunft beeinflusst und als Spielstein für den Aufstieg des Blumenzüchters betrachtet. \n Erst als sie vor der Krone erblüht, erkennen die Menschen, dass sie bereits von den Haken und Stichen blutig verletzt wurden."
  },
  Skill_4662_BattleDesc_0 = {
    Text = "Füge zufällig <Damage:[Damage:Arg1]> Schaden [Arg3] Mal zu. Am Ende der Runde stelle <Heal:[Heal:Arg2]> hp wieder her."
