  Skill_4663_AwakerSkillBackgroundStory = {
    Text = "Die kalte Maschine hat das Herz ersetzt, das Öl in den Hydraulikschläuchen hat das Blut ersetzt. Sie sollte kalt, rational und gemäß den Befehlen handeln. \n Doch ein fremder Wille regte sich leise in ihrem Körper. Er benötigt kein Blut, keine Wärme, sondern kann allein aus sich selbst heraus unmenschlichen Hass entfachen. Er sagt: Ergebe dich, du niederes, schwaches Wesen, und vernichte dich in meiner glühenden elektrischen Kugel."
  },
  Skill_4663_BattleDesc_0 = {
    Text = "Erhalte [Power:Arg1] Punkte vorübergehende <PowerIconKeywords:Stärke>. Erhalte <Posse:[Arg2]> Punkte s-Energie. Entferne den eigenen Zustand <WeaknessIconKeywords:Schwäche>. Jedes Mal, wenn eine Karte in den <DimensionalSpaceIconKeywords:Hyperraum> eingeht, verwandle dich in <DerivativeCardKeywords_14:“Mechanische Ausrüstung - Sammeln“>."
  },
  Skill_4663_BattleDesc_1 = {
    Text = "Erhalte [Power:Arg1] Punkte vorübergehende <PowerIconKeywords:Stärke>. Erhalte <Posse:[Arg2]> Punkte Keyflare. Entferne den eigenen Zustand <WeaknessIconKeywords:Schwäche>. Lege 1 Karte “Schlag“ mit <DepleteIconKeywords:Verbrauch> von Erica in deine Hand. Jedes Mal, wenn eine Karte in den <DimensionalSpaceIconKeywords:Hyperraum> eingeht, verwandle dich in <DerivativeCardKeywords_14:“Mechanische Ausrüstung - Sammeln“>."
  },
  Skill_4663_Desc_0 = {
    Text = "Erhalte [Power:Arg1] Punkte vorübergehende <PowerIconKeywords:Stärke>. Erhalte s-Energie in Höhe der Keyflare-Regeneration von Erica. Zerstreue deinen <WeaknessIconKeywords:Schwäche> Zustand. Jedes Mal, wenn eine Karte in den <DimensionalSpaceIconKeywords:Hyperraum> kommt, verwandle sie in <DerivativeCardKeywords_14:“Mechanische Ausrüstung - Sammeln“>."
  },
  Skill_4663_Desc_1 = {
    Text = "Erhalte [Power:Arg1] Punkte vorübergehende <PowerIconKeywords:Stärke>. Erhalte Silberschlüssel-Energie, die der Keyflare-Regeneration von Erica entspricht. Entferne den eigenen Zustand <WeaknessIconKeywords:Schwäche>. Lege 1 Karte “Schlag“ mit <DepleteIconKeywords:Verbrauch> von Erica in deine Hand. Jedes Mal, wenn eine Karte in den <DimensionalSpaceIconKeywords:Hyperraum> eingeht, verwandle dich in <DerivativeCardKeywords_14:“Mechanische Ausrüstung - Sammeln“>."
  },
