  Skill_4664_AwakerSkillBackgroundStory = {
    Text = "Die unsichtbare Seuche schleicht leise umher und bringt unendliches Leid und Wahnsinn.\n\nDer Bischof kann nachts nicht schlafen und ist unendlich traurig darüber, dass er das Leiden der Menschen nicht lindern kann.\n\n“Gnädiger Schöpfer, rette sie, ich bin bereit, all ihr Leid und ihren Kummer auf mich zu nehmen.“\n\nDa sandte der All-Vater ihm den “Segen“, damit er die mit den heiligen Schriften gravierte Steinplatte hielt und das Leiden und die Not beseitigte."
  },
  Skill_4664_Desc_0 = {
    Text = "Salvador erhält <Energy:[Energy:Arg1]> Punkte Aelius. <ExaltIconKeywords:Gnosis wecken>: Lege eine Karte <B02AFKeyWord:Liebe ist Schutz> auf die Hand. Am Ende der Runde erhalte [Power:Arg2] Punkte <PowerIconKeywords:Macht>"
  },
  Skill_4664_Desc_15 = {
    Text = "Salvador erhält <Energy:[Energy:Arg1]> Punkte Aelius. <ExaltIconKeywords:Erwecken>: Lege eine Karte <B02AFKeyWord:Heiligtum der Barmherzigkeit> auf die Hand. Am Ende der Runde erhalte [Power:Arg2] Punkte <PowerIconKeywords:Stärke>. Der Segen des Schöpfers und die Gesegnet seien die Knochen erhöhen die Rückgewinnung des Blutroten Ofens um 25%, und wenn „Ende des Leidens“ die „Befreiung“ wählt, wird der endgültige Schadensbonus, der durch die 1% maximale LP des Blutroten Ofens erhöht wird, von 2% auf 5% erhöht."
  },
