  Skill_4667_AwakerSkillBackgroundStory = {
    Text = "Das ist ein riesiges Labyrinth, das alle Dimensionen überschreitet.\nDer in das Labyrinth geratene Reisende muss sich einem unhöflichen Handel stellen.\nWenn er mit “Nein“ antwortet, wird der Reisende für immer im Labyrinth gefangen bleiben.\nWenn er mit “Ja“ antwortet, wird der Reisende mit verfluchten Nachkommen implantiert und alle Erinnerungen werden ausgelöscht.\nWas, du fragst, was der spezifische Inhalt des Handels ist?\nNiemand weiß, was der spezifische Inhalt des Handels ist, nicht einmal der blasse Labyrinthherr.\nEin Handel ist einfach ein Handel."
  },
  Skill_4667_Desc_0 = {
    Text = "[<DevouredIconKeywords:verschlingen>：Erhält [Power:Arg1] Punkte <PowerIconKeywords:Macht> und [Arg4] Punkte <AlertIconKeywords:Alarm>。]Erhält <Block:[Block:Arg2]> Punkte Schild. Verursacht [Poison:Arg3] Schichten <IntoxicationIconKeywords:Gift> auf alle Feinde"
  },
  Skill_4667_EffectNameList = {
    Text = "Macht,Alarm,Schild,Gift"
  },
  Skill_4667_Name = {
    Text = "Blasser Segen"
  },
  Skill_4667_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:verschlingen>: Erhält [Power:Arg1] Punkte <PowerIconKeywords:Stärke> und [Arg4] Punkte <AlertIconKeywords:Alarm>.]Erhalte <Block:[Block:Arg2]> Punkte Schild. Fügt allen Feinden [Poison:Arg3] Schichten <IntoxicationIconKeywords:Gift> zu. Ziehe 2 Nicht-Schlag VERTs-Befehlskarten von Agrippa, wodurch die Arithmetica-Kosten für 2 Nicht-Schlag VERTs-Befehlskarten von Agrippa in dieser Runde um -1 reduziert werden."
  },
  Skill_4667_PropertyNameList = {
    Text = "ANGskraft*Wertsteigerung1,VERTskraft*Wertsteigerung4,VERTskraft*Wertsteigerung2,ANGskraft*Wertsteigerung3"
  },
  Skill_4668_AwakerSkillBackgroundStory = {
    Text = "Er konnte nicht akzeptieren, dass er beinahe gestorben wäre. Er sollte unbesiegbar sein, sollte unzerstörbar sein. Wenn der menschliche Körper ein Hindernis für seinen Aufstieg zur höchsten Kraft ist, dann soll er seinen Körper aufgeben; wenn die Aufgabe seines Stammes ihm Stärke bringen kann, dann soll er die Vergangenheit begraben.\nEr warf das riesige Schwert ins tiefe Meer, um übermenschliche Kraft zu erlangen, und schwor, der Herrscher über alles zu werden.\nSogar die Existenz, die ihm Kraft gab, wird eines Tages zu seinen Füßen liegen."
  },
  Skill_4668_Desc = {
    Text = "Wähle: <O06_AFKeyWord1:Entfaltung> oder <O06_AFKeyWord2:Lauer>. Lege 3 Karten <DerivativeCardKeywords_17:\"Macht des Großschwerts\"> in deine Hand"
  },
  Skill_4668_EffectNameList = {
    Text = "Temporäre STR"
  },
  Skill_4668_Name = {
    Text = "Macht des Abgrunds"
  },
  Skill_4668_OverLimitUtlSkillDesc = {
    Text = "Wähle: <O06_AFKeyWord1:Usurpieren> oder <O06_AFKeyWord2:Ruhezustand>. Lege 3 Karten <DerivativeCardKeywords_17:“Klingenherrschaft“> in deine Hand. Wähle “Usurpieren“, erhöht sich der Grundschaden der in die Hand genommenen “Klingenherrschaft“ um 400%, die Arithmetica-Kosten werden auf 0 gesetzt. Wähle “Ruhezustand“, anstelle von “Klingenherrschaft“ in die Hand zu legen, lege 2 Karten “Enthauptungsschaden“ in die Hand und verleihe ihnen “Verbrauch“, “Vorbereiten 1“ und “Behalten“."
  },
  Skill_4669_AwakerSkillBackgroundStory = {
    Text = "Sie ist das Gefäß der Emotionen, die Fortsetzung der Gefühle.\nLass diese dichte Tinte fließen, lass diese Poesie vergeuden.\nDie Worte, die nie ausgesprochen wurden, werden in ihrem Gedichtband beginnen"
  },
  Skill_4669_Desc_0 = {
    Text = "Horla erhält <Energy:[Energy:Arg1]> Punkte Aliemus. <ExaltIconKeywords:Erwecken>: Sofort erhält sie 1 Schicht der Metapher für andere Emotionen außer der aktuellen Emotion. Zu Rundenbeginn erhält sie ebenfalls 1 Schicht. Jede Metapher kann maximal 3 Schichten haben. Jede Schicht der Metapher verbraucht bei einem Gedichtsprung <TransitionIconKeywords:Sprung> die entsprechende Metapher und erhält einen zusätzlichen Bonus."
  },
  Skill_4669_Desc_15 = {
    Text = "Horla erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Sofort 1 Stapelung <D06CardKeyWord1:Metapher> für jede Emotion außer der aktuellen Emotion erhalten. Zu jedem Rundenbeginn außerdem 1 Stapelung für jede andere 3 Emotionen erhalten, bis zu 3 Stapelungen pro Typ. Wenn ein Gedicht <TransitionIconKeywords:Sprung> auslöst, werden alle Stapelungen der entsprechenden <D06CardKeyWord1:Metapher> verbraucht und ein Bonus erhalten. Nach dem Freisetzen der Vernichtung löst Horlas nächste in dieser Runde gespielte Befehlskarte Sprung aus. Immer wenn Horla 3 oder mehr Stapelungen Metapher verbraucht, wird der Effekt der aktuellen Emotion vorübergehend um +[Arg2]% erhöht. Dieser Effekt ist nicht stapelbar."
  },
  Skill_4669_EffectNameList = {Text = "Aliemus"},
  Skill_4669_Name = {
    Text = "Präludiumvers"
  },
  Skill_4670_Desc = {
    Text = "Bei eigenem Tod teile sich in drei Leben als „II-Typ Aufgelöster Körper“, entsprechend ihrer eigenen"
  },
