  Skill_4694_AwakerSkillBackgroundStory = {
    Text = "In der düsteren Neuen-Tor-Gefängnis ist Wachsöl, das überall in Lentiniën zu finden ist, ebenfalls etwas Seltenes. \n Da es selten ist, sollte es an entscheidenden Orten verwendet werden, zum Beispiel bei der Bestrafung, auf der Haut ungehorsamer Kinder. \n Es ist kein spezielles Wachsöl; beim Fallen begleitet von tragischen Klagen und Schreien, doch in den Ohren des Mädchens klingt es wie elegante Verse."
  },
  Skill_4694_BattleDesc_0 = {
    Text = "Erhalte [Counterattack:Arg2] Schichten <RetaliateIconKeywords:Gegenangriff>. Reduziere vorübergehend allen Feinden [Exhaustion:Arg1] Punkte <ExhaustionIconKeywords:Stärke>, für jeden Feind erhalte [Power:Arg1] Punkte <PowerIconKeywords:Temporäre STR>. Entferne den Zustand <RetaliateIconKeywords:Gegenangriff> von allen Feinden."
  },
  Skill_4694_BattleDesc_2 = {
    Text = "Erhalte [Counterattack:Arg2] Schichten <RetaliateIconKeywords:Gegenangriff>. Reduziere vorübergehend die <PowerIconKeywords:Macht> aller Feinde um [Exhaustion:Arg1] Punkte. Für jeden Feind erhalte [Power:Arg1] Punkte <PowerIconKeywords:Temporäre STR>. Entferne den <RetaliateIconKeywords:Gegenangriff> Zustand aller Feinde. Erhalte <Energy:[Energy:Arg3]> Punkte Aliemus."
  },
  Skill_4694_Desc_0 = {
    Text = "Erhalte [Counterattack:Arg2] Schichten <RetaliateIconKeywords:Gegenangriff>. In dieser Runde stehle allen Feinden [Arg1] Punkte <PowerIconKeywords:Kraft>, wenn nur ein Feind vorhanden ist, werden die gestohlenen <PowerIconKeywords:Kraft> verdoppelt. Entferne den Status <RetaliateIconKeywords:Gegenangriff> von allen Feinden."
  },
  Skill_4694_Desc_2 = {
    Text = "Erhalte [Counterattack:Arg2] Schichten <RetaliateIconKeywords:Gegenangriff>. Stehle in dieser Runde allen Feinden [Arg1] Punkte <PowerIconKeywords:Stärke>, wenn nur ein Feind vorhanden ist, wird die gestohlene <PowerIconKeywords:Stärke> verdoppelt. Entferne alle feindlichen <RetaliateIconKeywords:Gegenangriff> Zustände. Erhalte <Energy:[Energy:Arg3]> Punkte Aliemus."
