  Skill_4727_Name = {Text = "Biss"},
  Skill_4728_AwakerSkillBackgroundStory = {
    Text = "Ich habe alles Menschliche aufgegeben! Ich werde in die Arme des tiefen Meeres zurückkehren!\nAber warum ist meine Verwandlung gescheitert?\nIst es das Spott des Schicksals? Oder meine Dummheit?\nDer wahnsinnige Caecus umarmt den zerbrochenen Speer und versucht, in die Tiefen des Meeres zu sinken.\nSolange ich zurückkehren und akzeptiert werden kann, werde ich alle Hindernisse vor mir beseitigen."
  },
