  Skill_47455_Name_1 = {Text = "Sandsack"},
  Skill_4745_AwakerSkillBackgroundStory = {
    Text = "Zwei Willen kämpfen und ringen in dem mechanischen Körper: einer strebt nach Zerstörung, der andere weigert sich zu kapitulieren. Doch der kleine Mensch kann nicht lange siegen; sie wird schließlich von der anderen Seite verschlungen werden und zu einem wahnsinnigen Gefäß werden, das nur für Zerstörung existiert. \n Daher entlässt sie all ihren Strom. Ein riesiger Lichtbogen umhüllt sie, der kurzschlussartige Körper gibt ein explosives Geräusch des Stroms von sich, sie wirft die angesammelte Energie nach vorne und gerät dann in eine kurze Lähmung. \n “Wenn ich mich nicht bewegen kann, kann ich nicht zerstören.“"
  },
  Skill_4745_Desc_0 = {
    Text = "Erica erhält [Arg4]% temporäre Krit. Rate und Krit. Schaden. Erhalte <Block:[Block:Arg2]> Punkte Schild. Verursacht <Damage:[Damage:Arg1]> Schaden und füge allen Feinden [Arg3] Schichten <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbarkeit> hinzu."
  },
  Skill_4745_Desc_2 = {
    Text = "Erica erhält [Arg4]% vorübergehende Krit. Rate und krit. Schaden. Erhalte <Block:[Block:Arg2]> Punkte Schild. Verursacht <Damage:[Damage:Arg1]> Schaden an allen Feinden und fügt [Arg3] Schichten <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbar> hinzu. Diese Fähigkeit profitiert zusätzlich von [Arg7] Mal <PowerIconKeywords:Stärke> und <AlertIconKeywords:Wachsam> Bonus."
  },
