  },
  Skill_4745_OverLimitUtlSkillDesc_0 = {
    Text = "Erica erhält [Arg4] % temporäre Krit. Rate und Krit. Schaden. Erhalte <Block:[Block:Arg6]> Punkte Schild. Verursache <Damage:[Damage:Arg5]> Schaden an allen Feinden und belege sie mit [Arg3] Stapelungen <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbar>. Ericas „Basisschlag \" verursacht 1 zusätzlichen Treffer, „Basisverteidigung\" gewährt 1 zusätzlichen Schild, hält 3 Runden an."
  },
  Skill_4745_OverLimitUtlSkillDesc_2 = {
    Text = "Erica erhält [Arg4]% temporäre Krit. Rate und Krit. Schaden. Erhalte <Block:[Block:Arg6]> Punkte Schild. Füge allen Gegnern <Damage:[Damage:Arg5]> Schaden zu und füge [Arg3] Schichten <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbar> hinzu. Diese Fähigkeit erhält zusätzlich [Arg7] Mal <PowerIconKeywords:Macht> und <AlertIconKeywords:Wachsam> Bonus. Ericas “Basis-Schlag“ fügt zusätzlich 1 Schaden zu, “Basis-Verteidigung“ erhält zusätzlich 1 Schild, und hält 3 Runden an."
  },
