  Skill_4745_tempBattleDesc_2 = {
    Text = "Erica erhält [Arg4]% vorübergehende Krit. Rate und krit. Schaden. Erhalte <Block:[Block:Arg2]> Punkte Schild. Verursacht <Damage:[Damage:Arg1]> Schaden an allen Feinden und fügt [Arg3] Schichten <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbar> hinzu. Diese Fähigkeit profitiert zusätzlich von [Arg7] Mal <PowerIconKeywords:Stärke> und <AlertIconKeywords:Wachsam> Bonus."
  },
  Skill_4745_tempBattleDesc_3 = {
    Text = "Erika erhält [Arg4]% temporäre Krit-Rate und Krit-Schaden. Erhält <Block:[Block:Arg2]> Punkte Schild. Fügt allen Feinden <Damage:[Damage:Arg1]> Schaden zu und appliziert [Arg3] Stapel <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbarkeit>. Diese Fähigkeit profitiert zusätzlich vom [Arg7]-fachen <PowerIconKeywords:Stärke>- und <AlertIconKeywords:Wachsamkeit>-Bonus. Bei nachfolgenden Einsätzen erhöht sich der Stärke- und Wachsamkeit-Bonus zusätzlich um das 1-Fache."
