  Skill_4745_tempOverLimitUtlSkillDesc_1 = {
    Text = "Erica erhält [Arg4] % Temporäre Kritische Trefferquote und Krit. Schaden. Erhalte <Block:[Block:Arg6]> Punkte Schild. Verursache an allen Feinden <Damage:[Damage:Arg5]> Schaden und verhänge [Arg3] Lagen <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbar>. Ericas „Basisschlag \" verursacht 1 zusätzlichen Schaden und „Basisverteidigung\" gewährt 1 zusätzlichen Schild, für 3 Runden."
  },
  Skill_4745_tempOverLimitUtlSkillDesc_2 = {
    Text = "Erika erhält [Arg4] % temporäre Krit-Rate und Krit-Schaden. Erhält <Block:[Block:Arg6]> Punkte Schild. Fügt allen Feinden <Damage:[Damage:Arg5]> Schaden zu und appliziert [Arg3] Stapel <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbarkeit>. Diese Fähigkeit profitiert zusätzlich vom [Arg7] -fachen <PowerIconKeywords:Stärke>- und <AlertIconKeywords:Wachsamkeit>-Bonus. Erikas „Basisangriff \" verursacht zusätzlich 1-mal Schaden, „Basisverteidigung\" gewährt zusätzlich 1-mal Schild, hält 3 Runden an."
  },
  Skill_4745_tempOverLimitUtlSkillDesc_3 = {
    Text = "Erika erhält [Arg4] % temporäre Krit-Rate und Krit-Schaden. Erhält <Block:[Block:Arg6]> Punkte Schild. Fügt allen Feinden <Damage:[Damage:Arg5]> Schaden zu und appliziert [Arg3] Stapel <WeaknessIconKeywords:Schwäche> und <VulnerabilityIconKeywords:Verwundbarkeit>. Diese Fähigkeit profitiert zusätzlich vom [Arg7] -fachen <PowerIconKeywords:Stärke>- und <AlertIconKeywords:Wachsamkeit>-Bonus. Bei nachfolgenden Einsätzen erhöht sich der Stärke- und Wachsamkeit-Bonus zusätzlich um das 1-Fache. Erikas „Basisangriff \" verursacht zusätzlich 1-mal Schaden, „Basisverteidigung\" gewährt zusätzlich 1-mal Schild, hält 3 Runden an."
