  Skill_47484_Name = {
    Text = "Fortg. Einblick"
  },
  Skill_4748_AwakerSkillBackgroundStory = {
    Text = "Die Kinder werden allmählich die Essenz der Märchen durchschauen und die Fabeln hinter den Mythen verstehen. In der menschlichen Sprache wird dieser Prozess als “Erwachsenwerden“ bezeichnet.\n Doch es gibt auch Kinder, die an den Gute-Nacht-Geschichten immer fester glauben. Sie sind hartnäckig überzeugt, dass es wirklich einen Regenbogen gibt und dass Zivilisationen im tiefen Meer versunken sind.\n Aurita liebt diese Geschichten und möchte diese Freude mit noch mehr Freunden teilen."
  },
  Skill_4748_Desc_0 = {
    Text = "<TentacleInjurieIconKeywords:Tentakelschaden> +[TentaclePower:Arg1]. Lege alle Handkarten ab und ziehe dieselbe Anzahl an Karten. Mische 1 „Drüsenspaltung“ in den Ablagestapel."
  },
  Skill_4748_Desc_1 = {
    Text = "<TentacleInjurieIconKeywords:Tentakelschaden> +[TentaclePower:Arg1]. Lege alle Handkarten ab und ziehe entsprechend der abgelegten Anzahl +1 Karten. Mische 1 „Drüsenaufspaltung“ in den Ablagestapel."
  },
  Skill_4748_EffectNameList = {
