  Skill_4749_Desc = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden [AttackTimes:Arg2] Mal"
  },
  Skill_4750_AwakerSkillBackgroundStory = {
    Text = "Geburt, erscheine, fortpflanze. \n In der zunehmend lösenden Realität, in der eintretenden dunklen Welt, im bald neugeborenen Nichts. \n Euer Dasein ist die Frucht des Opfers der Mutter, der Grund für das Bestehen der Mutter. \n Nachkomme der Reinheit, werde im neuen Welt wiedergeboren — in jener reinen, die alle Angst beseitigt hat, neuen Welt werde wiedergeboren."
  },
  Skill_4750_Desc_0 = {
    Text = "Thais erhält <Energy:[Energy:Arg1]> Punkte Wahnsinn. <ExaltIconKeywords:Gnosis wecken>: Sofort Erhalt von 1 <DerivativeCardKeywords_10:Heiligen Sohn>. Jedes Mal, wenn du ein Schlüsselkommando freisetzt, wird ein Embryo in deiner Hand in <DerivativeCardKeywords_10:Heiligen Sohn> umgewandelt"
  },
  Skill_4750_Desc_15 = {
    Text = "Thais erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Erhalte sofort 1 <DerivativeCardKeywords_10:Nachkomme der Reinheit>. Immer wenn eine Posse freigelassen wird, verwandle 1 Embryo auf der Hand in 1 <DerivativeCardKeywords_10:Nachkomme der Reinheit>. „Ritual des Überflusses \" legt zusätzlich 1 weitere Kopie auf deine Hand."
  },
  Skill_4750_EffectNameList = {Text = "Aliemus"},
  Skill_4750_Name = {
    Text = "Ad Matrem Vocatus"
  },
  Skill_47516_Desc_1 = {
    Text = "<PVPWeaponKeywords:Schicksalsring>: Am Rundenende wirft [Arg1] Karten der anderen erhobenen Körper ab und zieht entsprechend viele"
  },
  Skill_47516_Name_1 = {
    Text = "Entschlossenheit des Silberkabeljaus"
  },
  Skill_4751_AwakerSkillBackgroundStory = {
    Text = "Blitzend nicht, schau genau hin, der magische Moment ist gekommen; \nweiße Handschuhe, schwarzer Zylinder, ich erschaffe Luft aus bunten Karten. \nPrächtig wie ein bunter Streifen, funkelnd wie Pailletten, \ndiese traumhafte und wahnsinnige glitzernde Aufführung wird dich garantiert verblüffen!"
  },
  Skill_4751_Desc_0 = {
    Text = "Gebe allen Feinden <Damage:[Damage:Arg1]> Schaden, ziehe [Arg2] Karten. Für jede gezogene Casiah-Befehlskarte erleidet ein zufälliger Feind <Damage:[Damage:Arg1]> Schaden. Erhöhe den Grundschaden von Casiah um [Arg3]%"
  },
  Skill_4751_Desc_2 = {
    Text = "Gebe allen Feinden <Damage:[Damage:Arg1]> Schaden, ziehe [Arg2] Karten. Für jede gezogene Symptomkarte, Zustandskarte oder Casiah-Befehlskarte erleidet ein zufälliger Feind <Damage:[Damage:Arg1]> Schaden. Erhöhe den Grundschaden von Casiah um [Arg3]%"
  },
