  Skill_4788_Desc = {
    Text = "Füge beiden Seiten [Arg1] Schichten<VulnerabilityIconKeywords:verwundbar> zu. Erhalte „Schneid III“: Wenn unblocksierter Schaden verursacht wird, füge dem obersten Kartenstapel 3 Karten<DerivativeCardKeywords_23:„Wunde“> hinzu. Dauer 1 Runde"
