  Skill_4788_Name = {Text = "Todeskampf"},
  Skill_4789_AwakerSkillBackgroundStory = {
    Text = "Niemand kann sagen, warum das mit einem tropfenförmigen Silberkern verzierte Teddybärchen nach der Erweckung von Aigis so aussieht. Es könnte mit der Macht des Oberen, die Aigis innewohnt, zu tun haben, oder einfach eine Verformung sein, die durch die starke geistige Kraft verzerrt wurde.\n\n Wie dem auch sei, es scheint ein gewisses Selbstbewusstsein zu besitzen und trennt manchmal heimlich einen Teil von sich ab, der sich in ein aus Wolle bestehendes Feuerwerk verwandelt."
  },
  Skill_4789_Desc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden und fügt [Arg2] Runden <VulnerabilityIconKeywords:Verwundbar> hinzu. <EmbryoFusionIconKeywords:Embryofusion> +[Arg3]"
  },
  Skill_4789_Desc_3 = {
