  Skill_4800_Desc_0 = {
    Text = "Ryker erhält <Energy:[Energy:Arg1]> Punkte Aliemus. <ExaltIconKeywords:Erwecken>: Erhalte [Power:Arg2] Punkte <PowerIconKeywords:Stärke>. Erhalte in diesem Kampf ein gewähltes <C05_zaowu:“Das Erbe des Chaos“> Relikt oder erhöhe ein bereits besessenes <C05_zaowu:“Das Erbe des Chaos“>."
