  Skill_4800_Desc_15 = {
    Text = "Ryker erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Erhalte [Power:Arg2] <PowerIconKeywords:STR>. Erhalte in diesem Kampf ein gewähltes <C05_zaowu:„Das Erbe des Chaos\">-Relikt, oder verbessere ein bereits besessenes <C05_zaowu:„Das Erbe des Chaos\">-Relikt. Alle sechsseitigen Würfel von Ryker werden zu achtseitigen Würfeln aufgewertet."
