  Skill_4804_AwakerSkillBackgroundStory = {
    Text = "Die Flammen breiten sich aus und tauchen das Gewölbe des Theaters in smaragdgrüne Farben, als wäre es das klare und ruhige Wasser eines Sees am Morgen. \n Wie viele Menschen sind gekommen, um dieser smaragdgrünen Gestalt nachzujagen, und wie viele haben die fließenden und kraftvollen Tanzbewegungen ignoriert, nur um die vage sichtbaren weißen Arme und die eingebildeten Anblicke unter dem Rock zu sehen? \n Doch die Tänzerin steht nur erstarrt dort, in der sterbenden Pose, von den grünen Flammen verschlungen."
  },
  Skill_4804_Desc_0 = {
    Text = "Liz erhält <Energy:[Energy:Arg1]> Punkte Wahnsinn. <ExaltIconKeywords:Gnosis wecken>: Nach [Arg2] erlittenen Schaden legt Liz eine Karte mit <DepleteIconKeywords:erschöpfen> und <DerivativeCardKeywords_18:„Grünfeuer“> in die Hand, maximal 3 Mal pro Runde"
  },
  Skill_4804_Desc_15 = {
    Text = "Liz erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Für jede [Arg2] <plural value=\"[Arg2]\" singular=\"Instanz\" plural=\"Instanzen\"> von Schaden, die Liz austeilt, lege 1 <DerivativeCardKeywords_18:„Grüne Flammen\"> mit <DepleteIconKeywords:Erschöpfung> auf die Hand, bis zu 3 Mal pro Zug. Liz' ausgeteilter Schaden in diesem Kampf +[Arg3] für jede ihrer 3 Instanzen von Schaden."
