  Skill_4821_AwakerSkillBackgroundStory = {
    Text = "Ihr Labyrinth führt in jede Ecke der Welt.\nIn den dichten Wäldern, unter den Bibliotheken und in den Tiefen des Meeres gibt es Eingänge.\nNur durch die unglücklichen Seelen, die in das Labyrinth geraten sind, kann sie mühsam das Bild der Welt skizzieren.\nDie Reisenden verlieren sich in den sich ständig drehenden Durchgängen, sie selbst verliert sich in den sich ständig verändernden Geschichten.\nSie weiß alles, kann aber keinen Schritt mehr aus dem Labyrinth heraus machen."
  },
  Skill_4821_Desc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden und gleichwertige <IntoxicationIconKeywords:Vergiftung>. Bei Auslösung von Verschlingen wird „Blasser Wirbel“ aus dem Ablagestapel auf die Hand gelegt"
