  Skill_4822_AwakerSkillBackgroundStory = {
    Text = "In der endlosen Wanderung hat Tinct den Namen ihrer Heimat vergessen.\nIm Laufe der langen Jahre hat das Universum den Namen des toten Planeten vergessen.\nEr wird zusammen mit unzähligen aufgelösten und verlassenen Planeten als “Ödstern“ bezeichnet.\nIhr Gesang ist vielleicht der letzte Nachklang dieses Planeten am Rande der Realität."
  },
  Skill_4822_Desc_0 = {
    Text = "Tinktur erhält <Energy:[Energy:Arg1]> Punkte Wahnsinn. <ExaltIconKeywords: Gnosis wecken>: Erhöht den Grundschaden von Tinkturs „Schlag“ um [Arg2]%, und Tinkturs alle Karten erhalten 1 zufälligen Effekt, der am Ende des Kampfes entfernt wird"
  },
  Skill_4822_Desc_15 = {
    Text = "Tinct erhält <Energy:[Energy:Arg1]> Aliemus, <ExaltIconKeywords:Erwecken>: Tincts „Schlag \"-Grundschaden +[Arg2] %, alle Karten von Tinct erhalten 1 zufälligen Effekt, der am Ende des Kampfes entfernt wird. Wenn Tinct zum ersten Mal pro Runde eine „Fähigkeit\" spielt, wird 1 temporärer „Schlag \" mit 0 Arithmetica-Kosten generiert, die zufälligen Effekte dieses „Schlags\" x2."
  },
