  },
  Skill_59476_AwakerSkillBackgroundStory = {
    Text = "Vor dem Hören dieses Liedes hattest du nie wirklich Ohren. Nach dem Hören dieses Liedes wirst du nie wieder solche Klänge finden. Also konzentriere dich, halte den Atem an und preise dieses seltene Musikstück!"
  },
  Skill_59476_Desc_0 = {
    Text = "Hameln erhält <Energy:[Energy:Arg1]> Punkte Aliemus.<ExaltIconKeywords:Erwecken>: Zu Beginn der Runde lege eine „<DerivativeCardKeywords_64:Symphonie der Harmonie>\" auf die Hand.<DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_Desc_15 = {
    Text = "Hameln erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Zu Rundenbeginn wird 1 „<DerivativeCardKeywords_64:Symphonie der Harmonie>„ auf die Hand gelegt. Zu Rundenbeginn erhält Hameln für jede Befehlskarte mit „Ton„ <Energy:[Energy:Arg2]> Aliemus. Wenn „Urakkord„ entfesselt wird, erhöht sich für je 2 Befehlskarten mit „Ton„ die Schadensanzahl um +1<DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_EffectNameList = {Text = "Aliemus"},
  Skill_59476_Name = {
    Text = "Lobenswertes Meisterwerk"
  },
  Skill_59477_AwakerSkillBackgroundStory = {
    Text = "Woher stammt die Musik? Aus den opfernden Rituale, aus dem Gesang der Bauern, aus dem Heulen der Urmenschen, aus dem Zwitschern der Lerchen im Frühling, aus dem Wind der Kiefern und den Wellen des Meeres, aus den Erschütterungen der Erde und dem Einsturz der Berge... oder aus dem Chaos zwischen Himmel und Erde, dem Gemurmel der Götter im Traum."
  },
  Skill_59477_BattleDesc_0 = {
    Text = "Verursacht zufällig [Arg3] <plural value=\"[Arg3]\" singular=\"Mal\" plural=\"Mal\"> <Damage:[Damage:Arg1]> <PunctureDamagewords:Durchstechschaden>. Jeder Treffer bewirkt: Reduziere vorübergehend die <ExhaustionIconKeywords:STR> des Ziels um [Exhaustion:Arg2]; erhalte [Power:Arg2] <PowerIconKeywords:Temporäre STR>. Wähle 1 nicht abgeleitete Befehlskarte in deiner Hand ohne <DepleteIconKeywords:Verbrauch>, <HuihuanaKeywords:Rondino> oder <XushiAKeywords:Geladene Melodie> und füge „<HuihuanaKeywords:Rondino>„ hinzu. Falls keine Handkarten qualifiziert sind, verursache stattdessen 3 Mal zusätzlich Schaden."
  },
  Skill_59477_BattleDesc_2 = {
    Text = "Verursacht zufällig [Arg3] <plural value=\"[Arg3]\" singular=\"Mal\" plural=\"Mal\"> <Damage:[Damage:Arg1]> <PunctureDamagewords:Durchstechschaden>. Jeder Treffer bewirkt: Reduziere vorübergehend die <ExhaustionIconKeywords:STR> des Ziels um [Exhaustion:Arg2]; erhalte [Power:Arg2] <PowerIconKeywords:Temporäre STR>. Wähle 1 nicht abgeleitete Befehlskarte in deiner Hand ohne <DepleteIconKeywords:Verbrauch>, <HuihuanaKeywords:Rondino> oder <XushiAKeywords:Geladene Melodie> und füge „<HuihuanbKeywords:Rondino>„ hinzu. Falls keine Handkarten qualifiziert sind, verursache stattdessen 3 Mal zusätzlich Schaden."
  },
  Skill_59477_Desc_0 = {
    Text = "Verursacht zufällig <Damage:[Damage:Arg1]> Punkte <PunctureDamagewords:Durchstechschaden> 3 Mal. Bei jedem verursachten Schaden wird dem Ziel [Arg2] Punkte <PowerIconKeywords:Stärke> <TouquKeywords:gestohlen>. Wählt 1 Befehlskarte auf der Hand, die kein „<HuihuanaKeywords:Rondino>\" besitzt, nicht verbrauchbar und nicht abgeleitet ist, und fügt ihr „Rondino\" hinzu. Falls keine Hand-Karte hinzugefügt werden kann, werden stattdessen 3 zusätzliche Treffer verursacht."
  },
  Skill_59477_Desc_2 = {
    Text = "Verursacht zufällig <Damage:[Damage:Arg1]> Punkte <PunctureDamagewords:Durchstechschaden> 3 Mal. Bei jedem verursachten Schaden wird dem Ziel [Arg2] Punkte <PowerIconKeywords:Stärke> <TouquKeywords:gestohlen>. Wählt 1 Befehlskarte auf der Hand, die kein „<HuihuanbKeywords:Rondino>\" besitzt, nicht verbrauchbar und nicht abgeleitet ist, und fügt ihr „Rondino\" hinzu. Falls keine Hand-Karte hinzugefügt werden kann, werden stattdessen 3 zusätzliche Treffer verursacht."
  },
