  },
  Skill_61122_BattleDesc = {
    Text = "Zählt als “Schlag“. Verursache <Damage:[Damage:Arg1]> Punkte Schaden, dieser Schaden erhält einen 5-fachen Stärke-Bonus und löst 30% <BleedingIconKeywords:Bluten> des Ziels aus, erhalte [Arg3]% des verlorenen Lebens (<Heal:[Arg2]>). Nach dem Spielen wird es zu “<DerivativeCardKeywords_65:Blutrote Fesseln>“."
  },
  Skill_61122_Desc = {
    Text = "Zählt als “Schlag“. Verursacht <Damage:[Damage:Arg1]> Punkte Schaden, dieser Schaden erhält eine 5-fache Machtsteigerung und löst 30% <BleedingIconKeywords:Bluten> des Ziels aus, heilt 15% des verlorenen Lebens. Nach dem Spielen wird es zu “<DerivativeCardKeywords_65:Blutrote Fesseln>“."
