  },
  Skill_61123_AwakerSkillBackgroundStory = {
    Text = "Singe, Göttin! Singe über das Schicksal der Tochter von Tilos:\nVoller Blut und Tränen, Wut und Verzweiflung.\nIhr Hass brennt wie ein Feuer und verzehrt alles um sie herum, schließlich\nführte es zu ihrem eigenen Tod"
  },
  Skill_61123_Desc_0 = {
    Text = "Blutkette·Helot erhält <Energy:[Energy:Arg1]> Punkte Wahnsinn. <ExaltIconKeywords:Erwecken>: Lege eine Karte “<DerivativeCardKeywords_65:Blutrote Fesseln>“ in deine Hand. Die Befehlskarten von Blutkette·Helot erhalten “<RetainIconKeywords:Behalten>“. Zu Rundenbeginn erhöht sich der Grundschaden von Blutkette·Helot in diesem Kampf um [Arg2]%."
  },
  Skill_61123_Desc_15 = {
    Text = "Helot: Kette erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Eine „<DerivativeCardKeywords_65:Blutrote Fesseln>\" in die Hand legen, und Helot: Kettes Befehlskarten erhalten „<RetainIconKeywords:Behalten>\". Zu Rundenbeginn wird Helot: Kettes Grundschaden für diesen Kampf um +[Arg2] % erhöht. Nach dem Freigeben der Verherrlichung „Blutige Fesseln \" jeder einzigartigen „Helot: Kette\"-Befehlskarte in der Hand 50 Stapelungen <TempPowerKeywords:Temporär Verbessern> gewähren."
  },
  Skill_61123_EffectNameList = {
    Text = "Wahnsinn, erhöhter Schaden"
  },
  Skill_61123_Name = {
    Text = "Deklaration der Seelensammlerin"
  },
  Skill_61124_AwakerSkillBackgroundStory = {
    Text = "Klotho, Klotho, Göttin mit Spindel,\nWoher stammt dein Faden?\nSelbst ohne Ketten, armer Telemachus,\nkannst dem Schicksal nicht entkommen"
  },
  Skill_61124_Desc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Ziehe 1 Befehlskarte von Blutkette · Helot und reduziere die Arithmetica-Kosten der Befehlskarten von Blutkette · Helot um 1.] In dieser Runde fügt Blutkette · Helot beim aktiven Schaden zusätzlich [Arg2]% <BleedingIconKeywords:Bluten> hinzu. Verursacht <Damage:[Damage:Arg1]> Punkte Schaden."
  },
