  Skill_66349_AwakerSkillBackgroundStory = {
    Text = "Sie wusste um die Vergangenheit, die Gegenwart und die Zukunft.\nSie wusste, wie alles entsteht und wieder vergeht.\nIn ihrem Ohr hallte der Atem des „Ihn“"
  },
  Skill_66349_Desc_0 = {
    Text = "Wenn sich die Karte in der Hand befindet und die oberste Karte des Ziehstapels eine Befehlskarte ist, wird sie zu einer Kopie davon. Nach dem Spielen wird sie wiederhergestellt und du erhältst <Energy:[Energy:Arg1]> Punkte Wahnsinn"
  },
  Skill_66349_Desc_1 = {
    Text = "Wenn sich eine Karte im Deck befindet, die Karte, die oben im Ziehstapel liegt, eine Befehlskarte, wird sie zu einer Kopie mit Arithmetica-Kosten -1. Nach dem Ausspielen wird sie zurückgesetzt, erhalte <Energy:[Energy:Arg1]> Punkte Aelius"
