  Skill_66350_AwakerSkillBackgroundStory = {
    Text = "An der Tür des Silberschlüssels, kniet die Menschheit vor Seinem Thron und sucht nach der ultimativen Antwort.\nUnd sie ist die Wächterin, die dafür sorgt, dass gewarnt, erinnert und gewarnt wird.\nEs ist ihre Barmherzigkeit, es nicht zu offenbaren"
  },
  Skill_66350_BattleDesc_0 = {
