  Skill_66356_AwakerSkillBackgroundStory = {
    Text = "Alles im Leben.\nSie beherrscht Zeit und Raum, und aus ihren Fingerspitzen fließt die geordnete Welt.\nAlles vereint sich.\nAnorganisches und organisches Vermischen in Chaos, werden schließlich im Atem „Seiner“ ins Nichts zurückkehren"
  },
  Skill_66356_Desc_0 = {
    Text = "In dieser Runde Gesamtschaden eigener Befehlskarten +15%. Erhalte <Posse:[Arg1]> Keyflare. Zeige 5 Fähigkeitskarten aus dem aktuellen Reich, wähle bis zu 3 zum <FaxianKeywords:Entdecken> aus und mache sie zu Tawils Karten mit <DepleteIconKeywords:Verbrauch> und <RetainIconKeywords:Behalten>. Die nächste gespielte Befehlskarte von Tawil wirkt 2 Mal."
