  Skill_70299_AwakerSkillBackgroundStory = {
    Text = "Das Ziel, nach dem sie ihr ganzes Leben lang gesucht hat, liegt nun in greifbarer Nähe vor ihr. \n Die schwarze Tür strahlt eine tödliche Anziehung aus. \n Bevor sie die Tür aufstößt, hat sie 372 Möglichkeiten der Wahrheit entworfen. \n Nach dem Öffnen der Tür bleibt nur die 373. Möglichkeit übrig, die sie nicht wahrhaben will. \n Keine Wahl, sie kann nur fallen. \n Ihr Glück ist wirklich schlecht, sie selbst und die ganze Welt."
  },
  Skill_70299_BattleDesc = {
    Text = "Andere Erwecker erhalten <Energy:[Energy:Arg1]> Aliemus, verursachen [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"Stapelung\" plural=\"Stapelungen\"> <IntoxicationIconKeywords:Gift> auf allen Feinden und Temporäre Schadenamplifikation +[Arg3]%."
  },
  Skill_70299_Desc = {
    Text = "Andere Erwecker erhalten <Energy:[Energy:Arg1]> Aliemus, verursachen [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"Stapelung\" plural=\"Stapelungen\"> <IntoxicationIconKeywords:Gift> auf allen Feinden und Temporäre Schadenamplifikation +[Arg3]%. „Finale-Form“: Ziehe 3 zusätzliche Karten, erhalte 3 Arithmetica, löse 50% von <IntoxicationIconKeywords:Gift> auf allen Feinden aus und erhöhe den Basis-Aliemus von „Doll: Inferno“ um 50, bis zu 3 Mal."
  },
  Skill_70299_EffectNameList = {
    Text = "Wahnsinn, Vergiftung, verstärkter Schaden"
  },
  Skill_70299_Name = {
    Text = "Terminal, Tor der Wahrheit und des Abgrunds"
  },
  Skill_70299_OverLimitUtlSkillDesc = {
    Text = "Andere Erwecker erhalten <Energy:[Energy:Arg4]> Aliemus, verursachen [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"Stapelung\" plural=\"Stapelungen\"> <IntoxicationIconKeywords:Gift> auf allen Feinden, Temporäre Schadenamplifikation +[Arg3]% und erhöhen <IntoxicationIconKeywords:Gift>, <RetaliateIconKeywords:Konter> und Grundschaden aller Erwecker um 10%. In Anführer-Kämpfen wird eine zusätzliche Stapelung von „Finale“ erhalten."
  },
  Skill_70299_PropertyNameList = {
    Text = "$GrowValue1,ANGskraft*GrowValue2,$GrowValue3％"
  },
  Skill_70300_AwakerSkillBackgroundStory = {
    Text = "Wenn die blutrote Spore unter dem mechanischen Panzer anschwillt, webt der Messingresonator ein bienenstockartiges VERTsnetz. \n Das Myzel-Pulsnetz zerreißt den Raum, die Säure-Nebel ätzt Warninschriften ein, während der Lichtstrahl zur Abtrennung der Erinnerungen vorgeheizt wird – alles Fleisch, das die Grenze berührt, wird schließlich zu Präparaten, die im Petrischale zucken."
  },
  Skill_70300_BattleDesc = {
    Text = "Erhalte <Block:[Block:Arg1]> Schild. Erhalte <Energy:[Energy:Arg2]> Wahnsinn"
  },
  Skill_70300_Desc = {
