  Skill_70301_AwakerSkillBackgroundStory = {
    Text = "Die Scherenbeine stammen aus ihrer Vergangenheit und von ihrem Volk. Sie sind die Kraft, die sie nicht aufgegeben hat. Welche Bedeutung verbirgt sich hinter dem Lächeln, das erscheint, wenn die Scherenbeine die Brust des Feindes durchbohren?"
  },
  Skill_70301_BattleDesc = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Punkte Schaden. Erhält <Energy:[Energy:Arg2]> Punkte Aelius"
  },
  Skill_70301_Desc = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Punkte Schaden. “Schmelzen·Puppe“ erhält <Energy:[Energy:Arg2]> Punkte Wahnsinn."
