  },
  Skill_70302_AwakerSkillBackgroundStory = {
    Text = "Sie opferte sich selbst und erhielt dafür das Privileg, die Realität zu berühren. \nAls sie ihre Hand zurückzog, war ihre Seele bereits zu Wachs geschmolzen."
  },
  Skill_70302_BattleDesc_0 = {
    Text = "„Schmelzen: Dor\" erhält <Energy:[Energy:Arg1]> Punkte Aliemus. <ExaltIconKeywords:Erwecken>: Am Ende der Runde <Heal:[Heal:Arg2]> Punkte LP wiederherstellen und <Energy:[Energy:Arg4]> Punkte Aliemus erhalten. „Endgültige Form“: Keine LP-Wiederherstellung mehr, stattdessen bei allen Feinden [Arg3] % <IntoxicationIconKeywords:Gift> auslösen."
  },
  Skill_70302_BattleDesc_15 = {
    Text = "„Schmelzen: Dor\" erhält <Energy:[Energy:Arg1]> Punkte Aliemus. <ExaltIconKeywords:Erwecken>: Für jede Stufe „Ende\" erhöht sich der Schaden um +8%. „Das Ende der Illusion\" gewährt allen Erweckern 30% Basis-Aliemus. Am Ende der Runde <Heal:[Heal:Arg2]> Punkte LP wiederherstellen und <Energy:[Energy:Arg4]> Punkte Aliemus erhalten. „Endgültige Form\": Keine LP-Wiederherstellung mehr, stattdessen bei allen Feinden [Arg3] % <IntoxicationIconKeywords:Gift> auslösen."
  },
  Skill_70302_Desc_0 = {
    Text = "“Schmelzen · Dor“ erhält <Energy:[Energy:Arg1]> Punkte Wahnsinn. <ExaltIconKeywords:Erwecken>: Am Ende der Runde stelle <Heal:[Heal:Arg2]> Lebenspunkte wieder her und erhalte Wahnsinn in Höhe der eigenen Wutregeneration. “Endgültige Form“: Keine Lebenspunkte mehr wiederherstellen, stattdessen bei allen Feinden [Arg3] % <IntoxicationIconKeywords:Gift> auslösen."
  },
  Skill_70302_Desc_15 = {
    Text = "„Schmelzen: Dor\" erhält <Energy:[Energy:Arg1]> Punkte Aliemus. <ExaltIconKeywords:Erwecken>: Für jede Stufe „Ende“ erhöht sich der Schaden um +8%. „Das Ende der Illusion“ gewährt allen Erweckern 30% Basis-Aliemus. Am Ende der Runde <Heal:[Heal:Arg2]> Punkte LP wiederherstellen und Aliemus entsprechend der eigenen Wutregeneration erhalten. „Endgültige Form“: Keine LP-Wiederherstellung mehr, stattdessen bei allen Feinden [Arg3] % <IntoxicationIconKeywords:Gift> auslösen."
  },
  Skill_70302_EffectNameList = {
    Text = "Wahnsinn, Wiederherstellung, Giftverhältnis auslösen"
  },
  Skill_70302_Name = {
    Text = "Seelenfäule"
  },
  Skill_70302_PropertyNameList = {
    Text = "$GrowValue1,Konstitution*GrowValue2,$GrowValue3％,"
  },
  Skill_70303_AwakerSkillBackgroundStory = {
    Text = "Wenn wir immer auf dem Einwegweg der Vernichtung gehen, wäre es dann eine Gnade, schneller zu gehen? \n Wenn das Ende der Welt in einem Augenblick eintritt, wird der Schmerz auch in einem Augenblick gefangen sein. \n Die Menschen müssen sich nur mit den Geliebten umarmen und dann gemeinsam der Nichtigkeit der Vernichtung entgegensehen. \n Wenn am Ziel kein Schmerz mehr ist, zählt das dann auch als das Erreichen des Himmels?"
  },
  Skill_70303_BattleDesc_0 = {
    Text = "Füge allen Feinden <RealDamage:Festgesetzten Schaden> in Höhe von 30% ihrer maximalen LP zu (Minimum [Arg2]). Nach dem Einsatz wechseln die spezifischen Fähigkeiten von „Schmelzen · Dor“ zur „Ende-Form“."
  },
  Skill_70303_BattleDesc_3 = {
    Text = "Füge allen Feinden <RealDamage:Festgesetzten Schaden> in Höhe von 30% ihrer maximalen LP zu (Minimum [Arg2]) und stelle 30% der verlorenen LP wieder her (<Heal:[Heal:Arg3]>). Nach dem Einsatz wechseln die spezifischen Fähigkeiten von „Schmelzen · Dor“ zur „Ende-Form“."
  },
  Skill_70303_Desc_0 = {
    Text = "Füge jedem Feind <RealDamage:Festgesetzten Schaden> in Höhe von 25% seiner maximalen LP zu, mit einem Mindestschaden von [Arg1]% deiner maximalen LP. Nach dem Einsatz wechseln die spezifischen Fähigkeiten von „Schmelzen · Dor“ zur „Ende-Form“. Der Effekt von „Das Ende der Illusion“ wird nur einmal aktiviert."
  },
  Skill_70303_Desc_3 = {
    Text = "Füge allen Feinden <RealDamage:Festgesetzten Schaden> in Höhe von 30% ihrer maximalen LP zu. Dieser Schaden beträgt mindestens [Arg1]% deiner maximalen LP. Stellt 30% der verlorenen LP wieder her. Nach dem Einsatz wechseln die spezifischen Fähigkeiten von „Schmelzen · Dor“ zur „Ende-Form“. Der Effekt von „Das Ende der Illusion“ wird nur einmal aktiviert."
  },
