  Skill_78782_AwakerSkillBackgroundStory = {
    Text = "In dem schwankenden Pendel beginnt die Welt, ausgelöscht zu werden.\nIn deinen Augen, in deinem Herzen, in deinem Schädel bleibt nur noch eine Gestalt übrig.\nDas ist die Erlösung – und zugleich eine Sackgasse."
  },
  Skill_78782_BattleDesc = {
    Text = "Heile <Heal:[Heal:Arg1]> HP [Arg2] Mal, entferne vorübergehend alle <MadnessIconKeywords:madness> Zustände von Gegnern und lasse sie vorübergehend [Exhaustion:Arg3] Punkte von <ExhaustionIconKeywords:strength> verlieren. <WormholeKeywords:quasar>: Gewinne [Power:Arg4] Punkte von <PowerIconKeywords:strength>."
  },
  Skill_78782_Desc = {
    Text = "Stelle <Heal:[Heal:Arg1]> Punkte Leben wieder her, entferne vorübergehend alle <MadnessIconKeywords:Wahnsinn>-Zustände des Feindes und reduziere temporär dessen <PowerIconKeywords:Kraft> um [Exhaustion:Arg3] Punkte. <WormholeKeywords:Quasar>: Erhalte [Power:Arg4] Punkte <PowerIconKeywords:Kraft>."
  },
  Skill_78782_EffectNameList = {
