  },
  Skill_78783_AwakerSkillBackgroundStory = {
    Text = "Ihre Stimme ist sanft und vertraut und windet sich in der unsichtbaren Dunkelheit deines Inneren. \nNiemand kann von einer Existenz außerhalb seiner selbst besiegt werden. Du selbst bist ihre Waffe."
  },
  Skill_78783_BattleDesc = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Punkte Schaden [Arg2]-mal, erhält <Energy:[Energy:Arg5]> Punkte Aelius. <WormholeKeywords:Quasar>: Erhalte [Power:Arg4] Punkte <PowerIconKeywords:Stärke>."
  },
  Skill_78783_Desc = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Punkte Schaden. Clementine erhält <Energy:[Energy:Arg3]> Punkte Aelius. <WormholeKeywords:Quasar>: Erhält [Power:Arg4] Punkte <PowerIconKeywords:Kraft>."
