  Skill_83576_Name = {
    Text = "Dilemma des Navigators"
  },
  Skill_83779_AwakerSkillBackgroundStory = {
    Text = "Die unendlichen salzigen Gewässer verschlingen sie und schützen sie zugleich. \n In diesem erstickenden Gefühl des Eintauchens nimmt sie den tiefen Ozean wahr und verschmilzt mit dem tiefen Ozean. \n Eines Tages wird der Ozean vollkommen ruhig sein, und jedes Schiff, das über die Meeresoberfläche segelt, wird Frieden geschenkt bekommen. \n Sie wartet auf diesen Tag, den “Tag des Erscheinens des Göttlichen Reiches“."
  },
  Skill_83779_Desc_0 = {
    Text = "Kephasant erhält <Energy:[Energy:Arg1]> Wahnsinn. <ExaltIconKeywords:Geistiges Erwachen>: Erhalte 1 Tentakel und füge 2 “<DerivativeCardKeywords_106:Pilot>“ deiner Hand hinzu. Wechsle in die “Stille-Meer“-Haltung und erhalte <Block:[Block:Arg2]> Schild. Abklingzeit: 3 Runden."
  },
  Skill_83779_Desc_15 = {
    Text = "Kephasant erhält <Energy:[Energy:Arg1]> Punkte Wahnsinn. <ExaltIconKeywords:Erwecken>: Erhalte 1 Tentakel und füge 2 Karten „<DerivativeCardKeywords_106:Pilot>\" deiner Hand hinzu. Jedes Mal, wenn die erste Karte „Bestrafung\" und „Unheilvolles Semaphor\" gespielt wird, füge 1 zusätzliche Karte „<DerivativeCardKeywords_106:Pilot>\" deiner Hand hinzu, und die Effekte von „<DerivativeCardKeywords_106:Pilot>\" werden um 50 % erhöht. Wechsle in die „Ruhiges Meer\"-Haltung und erhalte <Block:[Block:Arg2]> Schild. Abklingzeit: 3 Runden."
  },
  Skill_83779_EffectNameList = {
    Text = "Wahnsinn, Schild"
