  Skill_83780_AwakerSkillBackgroundStory = {
    Text = "Die Wolken werden über die Veränderungen des Wetters informieren, die Wellen erzählen von den Veränderungen der Strömungen, aber wenn der Sturm wirklich kommt, kann selbst das größte Schiff nur hilflos mit den Wellen treiben. \n In diesem Moment ist die Berechnung und Anleitung des Lotsen der letzte Ausweg für alle Überlebenden. \n Erfülle daher deine Pflicht, selbst wenn der Blitz dich trifft, sollst du inmitten des Schmerzes einen Hauch von Licht erstrahlen lassen, um die Richtung zum Ufer zu weisen. \n Das ist deine Mission, die du erfüllen musst."
  },
  Skill_83780_BattleDesc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild und [Arg2] temporäre Tentakel. Lege alle Karten auf der Hand ab und ziehe die gleiche Anzahl an Karten."
