  },
  Skill_89777_AwakerSkillBackgroundStory = {
    Text = "Er wurde nie in irgendeine Kampftechnik unterrichtet, doch die Kraft des Widerstands war bereits tief in seinem Lebensinstinkt verwurzelt."
  },
  Skill_89777_BattleDesc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden. Erhalte <Energy:[Energy:Arg2]> Wahnsinn. <WormholeKeywords:Quasar>: Mische 1 “<DerivativeCardKeywords_107:Schwarze Feder>“ in deinen Ziehstapel. Erhalte <Block:[Block:Arg3]> Schild."
  },
  Skill_89777_Desc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden. Castor erhält <Energy:[Energy:Arg2]> Wahnsinn. <WormholeKeywords:Quasar>: Mische 1 “<DerivativeCardKeywords_107:Schwarze Feder>“-Karte in den Nachziehstapel, erhalte <Block:[Block:Arg3]> Schild."
