  },
  Skill_89778_AwakerSkillBackgroundStory = {
    Text = "Er ist dumm, stur und hat sich nie verändert. Auch wenn er nur einen einsamen Schrei ausstoßen kann, wird er sich niemals Ketten und Klingen beugen. Er will mit seinem unversehrten, spitzen Schnabel jede Ritze im Käfig anpicken. Wenn die schwarzen Flügel den Rand der Nacht durchbrechen, wird er die letzte Feder nehmen, seinen Schatten mitnehmen und ins Licht jenseits des Sturms fliegen."
  },
  Skill_89778_Desc = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild, mische [Arg2] Karten <DerivativeCardKeywords_107:Schwarze Feder> in den Nachziehstapel."
  },
