  },
  Skill_89778_OverLimitUtlSkillDesc = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild, der in dieser Runde durch „<DerivativeCardKeywords_107:Schwarze Feder>\" behaltene Schild erhöht sich um <Block:[Block:Arg5]>. Jedes Mal, wenn du „<DerivativeCardKeywords_107:Schwarze Feder>\" spielst, füge dem Ziel zusätzlich [Corrosion:Arg4] Schichten <Corrosion:Korrosion> hinzu. Mische [Arg2] Karten „<DerivativeCardKeywords_107:Schwarze Feder>\" in den Ziehstapel und lege [Arg3] Karten „<DerivativeCardKeywords_107:Schwarze Feder>\" auf die Hand."
  },
  Skill_89778_PropertyNameList = {
