  Skill_89779_BattleDesc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg2]> Schaden, ziehe [Arg1] Karten. Behalten: Erhalte <Block:[Block:Arg3]> Schild. Verbraucht."
  },
  Skill_89779_BattleDesc_3 = {
    Text = "Verursacht <Damage:[Damage:Arg2]> Schaden, ziehe [Arg1] Karten. Erhalte 1 Punkt Arithmetica für jeweils 3 ausgespielte Karten. Der endgültige Schaden, den Castor verursacht, erhöht sich um 10 % ([Arg4]/3). Behalten: Erhalte <Block:[Block:Arg3]> Schild. Verbraucht."
  },
  Skill_89779_Desc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg2]> Schaden, ziehe [Arg1] Karten. Behalten: Erhalte <Block:[Block:Arg3]> Schild. Verbraucht."
