  },
  Skill_89779_Name = {
    Text = "Schwarze Feder"
  },
  Skill_89780_AwakerSkillBackgroundStory = {
    Text = "Um der grausamen Ausbeutung und dem wiederholten Verlust entgegenzutreten, wird er diese Flügel für immer vor seinem jüngeren Bruder schützen. Bis jede Feder zu Asche verbrannt ist, bis er selbst als Erster durch das Tor des Todes schreitet."
  },
  Skill_89780_BattleDesc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild. Erhalte <Energy:[Energy:Arg2]> Punkte Wahnsinn. <WormholeKeywords:Quasar>: Mische 1 Karte „<DerivativeCardKeywords_107:Schwarze Feder>“ in den Ziehstapel und erhalte <Block:[Block:Arg3]> Punkte Schild."
  },
  Skill_89780_Desc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Schildpunkte. Castor erhält <Energy:[Energy:Arg2]> Wahnsinnspunkte. <WormholeKeywords:Quasar>: Mische 1 Karte “<DerivativeCardKeywords_107:Schwarze Feder>“ in den Nachziehstapel und erhalte <Block:[Block:Arg3]> Schildpunkte."
