  },
  Skill_89781_AwakerSkillBackgroundStory = {
    Text = "Seine Flügel breiten sich aus wie ein breiter Schild, jede Feder verbindet sich mit einem widerstandsfähigen Knochen und zittert über deinem Kopf. \n Der schwarze Schatten hüllt dich ein und schirmt das Sonnenlicht, den Wind, den Regen und den Schaden vollständig ab und schafft einen sicheren Himmel. \n „Berühre es nicht, lass diese dunklen Flüche einfach dem Täter zurückgegeben werden.“"
  },
  Skill_89781_Desc_0 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild und <WeaknessIconKeywords:schwach> alle Gegner für 1 Runde. <WormholeKeywords:Quasar>: Mische 1 Karte “<DerivativeCardKeywords_107:Schwarze Feder>“ in den Nachziehstapel und erhalte <Block:[Block:Arg3]> Punkte Schild."
  },
  Skill_89781_Desc_2 = {
    Text = "Erhalte <Block:[Block:Arg1]> Punkte Schild, <WeaknessIconKeywords:Schwäche> alle Gegner für 1 Runde, erhalte für jede Karte “<DerivativeCardKeywords_107:Schwarze Feder>“ in deiner Hand <Energy:[Energy:Arg2]> Punkte Wahnsinn. <WormholeKeywords:Quasar>: Mische 1 Karte “<DerivativeCardKeywords_107:Schwarze Feder>“ in den Ziehstapel und erhalte <Block:[Block:Arg3]> Punkte Schild."
