  Skill_89782_AwakerSkillBackgroundStory = {
    Text = "Er ist nicht daran gewöhnt zu ertragen, diese Flügel können auch einen wütenden Wirbel erzeugen. \n Alles Fleisch wird von den scharfen Zähnen des Windes zerfetzt und blutig in den Bauch des Todes geworfen. \n Aber fürchte dich nicht, er wird deinen Namen im Auge des Sturms platzieren, in der Ruhe des Zentrums."
  },
  Skill_89782_Desc_0 = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden [Arg2] mal, der temporäre kritische Schaden aller anderen Verbündeten erhöht sich um [Arg3]%. <WormholeKeywords:Quasar>: Mische 1 Karte “<DerivativeCardKeywords_107:Schwarze Feder>“ in den Nachziehstapel, erhalte <Block:[Block:Arg4]> Punkte Schild."
  },
  Skill_89782_Desc_2 = {
    Text = "Fügt <Damage:[Damage:Arg1]> Schaden [Arg2] <plural value=\"[Arg2]\" singular=\"time\" plural=\"times\"> zu, erhöht den Temporären Kritischen Schaden anderer Verbündeter um [Arg3] % von Castors Krit. Schaden. Für jede in diesem Zug gespielte „<DerivativeCardKeywords_107:Schwarze Feder>\" werden die Arithmetica-Kosten um 1 gesenkt. <WormholeKeywords:Quasar>: Mische 1 „<DerivativeCardKeywords_107:Schwarze Feder>\" in den Ziehstapel und erhalte <Block:[Block:Arg4]> Schild."
  },
