  Skill_95811_AwakerSkillBackgroundStory = {
    Text = "Das Papier der Einladung stammt von zarter Haut. Die Dekoration der Einladung stammt von glattem Schädels. Der Text der Einladung stammt von frischem Blut. Die Unterschrift der Einladung stammt von dem leidenschaftlichen Gastgeber des Königspalastes. \n Doresain sendet Ihnen eine aufrichtige Einladung, Sie zu diesem Bankett, das Ihnen gehört, zu kommen."
  },
  Skill_95811_Desc_0 = {
    Text = "Doresain erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Erhalte [Power:Arg2] <PowerIconKeywords:STR>, und der von Doresain verursachte Schaden erhält einen zusätzlichen [Arg3]% STR-Bonus. Wenn Doresain in einer Runde zum ersten Mal tötet, verursache <RealDamage:Festgesetzten Schaden> in Höhe von 50% des Überschussschadens an andere Feinde."
  },
  Skill_95811_Desc_15 = {
    Text = "Doresain erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Erhalte [Power:Arg2] <PowerIconKeywords:STR>. Der von Doresain verursachte Schaden erhält einen zusätzlichen [Arg3]% STR-Bonus. Verursache Festgesetzten Schaden in Höhe von [Arg4]% der aktuellen LP an alle Feinde. Nach Doresains erstem Töten pro Runde verursache <RealDamage:Festgesetzten Schaden> an andere Feinde in Höhe von 100% des Überschussschadens."
  },
