  Skill_95817_AwakerSkillBackgroundStory = {
    Text = "Neben dem Gericht selbst ist auch die Art und Weise, wie man speist, ein wichtiger Aspekt der kulinarischen Kunst.\nDie Gabel, aus den Knochen des Feindes gefertigt, dringt tief in die Seele des Feindes ein.\nJedes Gericht ist eine sorgfältig vorbereitete Wiedersehensfeier."
  },
  Skill_95817_BattleDesc = {
    Text = "Füge dem Feind mit dem niedrigsten Leben <Damage:[Damage:Arg4]> Schaden zu, genieße einen [Arg2]%igen Kraftbonus und erhalte [Power:Arg3] <PowerIconKeywords:Kraft>."
