  Skill_95818_Desc = {
    Text = "Verursacht <Damage:[Damage:Arg1]> Schaden – je niedriger das Leben des Gegners, desto höher der Schaden, maximal <Damage:[Damage:Arg2]> Schaden. Absorbiert alle anderen Ghuls und erhält für jeden absorbierten Ghul [Arg3] Exemplare <Guaiwucanhai:Trümmer> und [Arg4] Schichten <Guaiwusiwangdikang:Todwiderstand>."
  },
  Skill_95818_Name = {
    Text = "Pandemonium-Glut"
  },
  Skill_95819_BattleDesc = {
    Text = "Entferne alle „Sättigung„ Stapelungen, wirf alle Handkarten ab. Lege die durch <DerivativeCardKeywords_111:„Seelenfressen\"> entfernten Karten in deine Hand, setze ihre Arithmetica-Kosten auf 0. Falls am Ende der Runde in der Hand: Lege zufällig eine Kopie einer entfernten Karte in deine Hand, setze ihre Arithmetica-Kosten auf 0 und erhalte Verbrauch und Nichtigkeit."
  },
  Skill_95819_Desc = {
    Text = "Entferne alle „Sättigung„ Stapelungen, wirf alle Handkarten ab. Lege die durch <DerivativeCardKeywords_111:„Seelenfressen\"> entfernten Karten in deine Hand, setze ihre Arithmetica-Kosten auf 0. Falls am Ende der Runde in der Hand: Lege zufällig eine Kopie einer entfernten Karte in deine Hand, setze ihre Arithmetica-Kosten auf 0 und erhalte Verbrauch und Nichtigkeit."
  },
  Skill_95819_Name = {
    Text = "Gedächtnisresonanz"
  },
  Skill_95820_AwakerSkillBackgroundStory = {
    Text = "Reiß deine Maske ab. Lass deine Vorurteile los. Tritt auf die Tanzfläche und umarme deinen lang vergessenen Tanzpartner. \n Wie lange hat es das schöne Mondlicht nicht mehr gesehen? Wie lange hat es keine zarten Liebesworte mehr gehört? \n Hör zu, es sehnt sich nach dir, so wie du dich nach ihm sehnst. \n Biss zu, verschlinge es. In diesem unvergleichlichen Festmahl vollziehen Lebewesen und Tote ihre gemeinsame Erhebung."
  },
  Skill_95820_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen> :<DerivativeCardKeywords_110:> Die aktuelle Wahnsinnsexplosion erhöht die Krit. Rate um [Arg2]%, erhalte [Power:Arg1] Punkte <PowerIconKeywords:Stärke>.] Verursacht <Damage:[Damage:Arg3]> Punkte Schaden an dem Feind mit dem niedrigsten Leben, erhält [Arg4]% Schadenbonus. Für jedes 1% Lebensverlust des Ziels erhöht sich der Gesamtschaden der aktuellen Wahnsinnsexplosion um 3%. Wenn du aktuell 3 <CarcassKeywords:Trümmer> besitzt, wird diese konsumiert, heile <Heal:[Heal:Arg5]> Lebenspunkte und verdopple den Krit. Schadenbonus der aktuellen Wahnsinnsexplosion (aktuell besitzt du [Arg6]/3 <CarcassKeywords:Trümmer>)."
  },
  Skill_95820_BattleDesc_3 = {
    Text = "[<DevouredIconKeywords:Verschlingen> :<DerivativeCardKeywords_114:> Die kritische Trefferquote dieser Wahnsinnsexplosion +[Arg2]%, erhalte [Power:Arg1] Punkte <PowerIconKeywords:Stärke>.] Verursacht <Damage:[Damage:Arg3]> Punkte Schaden an dem Feind mit dem niedrigsten Lebenspunkt, genießt [Arg4]% Stärke-Bonus. Für jedes 1% Lebensverlust des Ziels erhöht sich der Gesamtschaden dieser Wahnsinnsexplosion um 3%. Wenn du aktuell 3 <CarcassKeywords:Trümmer> hast, dann verzehre sie, heile <Heal:[Heal:Arg5]> Lebenspunkte und verdopple den kritischen Schaden-Bonus dieser Wahnsinnsexplosion (aktuell hast du [Arg6]/3 <CarcassKeywords:Trümmer>)."
  },
  Skill_95820_Desc_0 = {
    Text = "[<DevouredIconKeywords:Verschlingen> :<DerivativeCardKeywords_110:> Bei diesem Ausbruch erhöht sich die Krit. Rate um [Arg2]%, erhalte [Power:Arg1] Punkte <PowerIconKeywords:Stärke>.] Verursacht <Damage:[Damage:Arg3]> Punkte Schaden beim Feind mit dem niedrigsten Leben, erhält [Arg4]% Schadenbonus, für jedes 1% Lebensverlust des Ziels erhöht sich der Gesamtschaden dieses Ausbruchs um 3%. Wenn du aktuell 3 <CarcassKeywords:Trümmer> besitzt, esse sie, heile <Heal:[Heal:Arg5]> LP und verdopple den Schadenbonus für kritische Treffer bei diesem Ausbruch."
  },
  Skill_95820_Desc_3 = {
    Text = "[<DevouredIconKeywords:Verschlingen> :<DerivativeCardKeywords_114:> Die Krit. Rate dieser Wahnsinnsexplosion +[Arg2]%, erhalte [Power:Arg1] Punkte <PowerIconKeywords:Stärke>.] Verursacht <Damage:[Damage:Arg3]> Punkte Schaden an dem Feind mit dem niedrigsten Leben, genießt [Arg4]% Stärke-Bonus, und für jedes 1% Lebensverlust des Ziels erhöht sich der Gesamtschaden dieser Wahnsinnsexplosion um 3%. Wenn du derzeit 3 <CarcassKeywords:Trümmer> besitzt, wird diese konsumiert, heile <Heal:[Heal:Arg5]> Leben und verdopple den Bonus auf den kritischen Schaden dieser Wahnsinnsexplosion."
  },
  Skill_95820_EffectNameList = {
    Text = "Macht, Schaden, Heilung"
  },
  Skill_95820_Name = {
    Text = "Nekrotische Gala"
  },
  Skill_95820_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:Verschlingen>: <DerivativeCardKeywords_114:>Krit. Rate dieser Verherrlichung +[Arg2] %, erhalte [Power:Arg1] <PowerIconKeywords:Stärke>.] Krit. Rate dieser Verherrlichung +25%, Grundschaden um 50% erhöht. Verursache <Damage:[Damage:Arg7]> Schaden beim Gegner mit den niedrigsten LP, erhalte [Arg4] % Stärke-Bonus, der Gesamtschaden dieser Verherrlichung wird um 100% erhöht, und für jeden 1% Verlust an LP des Ziels erhöht sich der Schaden um zusätzlich 3%. Wenn du aktuell 3 [Trümmer] hast, werden diese konsumiert, heile <Heal:[Heal:Arg5]> LP und verdopple den Krit. Schaden-Bonus dieser Verherrlichung(aktuell besitzt du [Arg6] /3 Trümmer)."
  },
