  Skill_97915_BattleDesc_0 = {
    Text = "Katyusha erhält <Energy:[Energy:Arg1]> Punkte Aliemus. <ExaltIconKeywords:Erwecken>: Zu Beginn der Runde wird einer Befehlskarte von Katyusha in deiner Hand zusätzlich 1 Stufe von <HuoyanKeywords4:Lebendige Flamme> verliehen. Spiele die Befehlskarte, die 3 Stufen von <HuoyanKeywords4:Lebendige Flamme> verleiht, und lasse sie dann zurück zur Hand gehen."
  },
  Skill_97915_BattleDesc_15 = {
    Text = "Katyusha erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Gewähre zu Rundenbeginn zusätzlich 1 Stapelung <HuoyanKeywords4:Lebendige Flamme> auf 1 von Katyushas Befehlskarten auf der Hand. Nachdem eine Befehlskarte mit 3 Stapelungen <HuoyanKeywords4:Lebendige Flamme> gespielt wurde, bringe sie Zurück zur Hand. Gesamtschaden und STR–Effekt pro Stapelung von „Lebendige Flamme„ +30%."
  },
  Skill_97915_Desc_0 = {
    Text = "Katygra erhält [Energy:Arg1] Punkt(e) Wahnsinn. <ExaltIconKeywords:Geistiges Erwachen>: Zu Beginn des Spielzugs erhält eine zufällige “Befehlskarte“ von Katygra auf der Hand 1 Stufe “<HuoyanKeywords:Lebendige Flamme>“. Wenn eine Befehlskarte mit 3 Stufen “<HuoyanKeywords:Lebendige Flamme>“ gespielt wird, kehrt sie auf die Hand zurück."
  },
  Skill_97915_Desc_15 = {
