  Skill_98984_AwakerSkillBackgroundStory = {
    Text = "Fürchte dich nicht vor meinem Blick, komm zu mir, komm näher zu mir... \n In der prächtigen Illusion, die mit dem Pinsel erschaffen wurde, lass mich dir die höchste Schönheit verleihen."
  },
  Skill_98984_Desc_0 = {
    Text = "[<DevouredIconKeywords:verschlingen>: Die nächste ausgespielte Befehlskarte in dieser Runde hat einen Arithmetica-Verbrauch von -2.]Erhalte [Power:Arg1] Punkte <PowerIconKeywords:Stärke>. Der finale Schaden, der durch Wahnsinnsexplosionen anderer Erwecker in dieser Runde verursacht wird, sowie der Schutz und die Lebensregeneration erhöhen sich um [Arg2]%. <FaxianKeywords:Entdecken> 3 Karten mit <Chuanggoukeyin:Erstellte Prägung> der kämpfenden Erwecker “Fähigkeit“, wähle 1 Karte und lege sie in deine Hand und verleihe ihr <DepleteIconKeywords:Verbrauch> und <RetainIconKeywords:bewahren>."
  },
  Skill_98984_Desc_2 = {
    Text = "[<DevouredIconKeywords:Verschlingen>: Die nächste gespielte Befehlskarte in dieser Runde hat -2 Zugkosten.] Erhalte [Power:Arg1] Punkte <PowerIconKeywords:Stärke>. Der endgültige Schaden, den andere Erwecker in dieser Runde durch Wahnsinn verursachen, sowie Schild und Lebensrückgewinnung erhöhen sich um [Arg2] %. <FaxianKeywords:Entdecken> 3 [Fähigkeiten] von kämpfenden Erweckern mit <Chuanggoukeyin:Konstruktion des Siegels>, wähle 1 Karte und lege sie in deine Hand, und verleihe ihr <DepleteIconKeywords:Verbrauch> und <RetainIconKeywords:bewahren>."
  },
  Skill_98984_EffectNameList = {Text = "Stärke"},
  Skill_98984_Name = {
    Text = "Wahrheit ist auch eine Illusion"
  },
  Skill_98984_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:verschlingen> :Die nächste gespielte Befehlskarte in dieser Runde hat -2 Rechenleistungskosten.]Erhalte [Power:Arg1] Punkte <PowerIconKeywords:Macht>. Der endgültige Schaden, Schild und Lebensregeneration, die durch Wahnsinnsexplosionen anderer Erwachter in dieser Runde verursacht werden, werden um [Arg2]% erhöht. Erhalte 1 Schicht <Kuangxiang:Wahn>. <FaxianKeywords:Entdecken> 2 Mal die “Fähigkeit“ der Kampf-Erwecker mit <Chuanggoukeyin:hohen Orisonen>, wähle 1 Karte und lege sie in deine Hand, und verleihe ihr <DepleteIconKeywords:Verbrauch> und <RetainIconKeywords:bewahren>."
  },
  Skill_98984_PropertyNameList = {
    Text = "ANGskraft*Wertsteigerung1"
  },
  Skill_98985_AwakerSkillBackgroundStory = {
    Text = "Die Schatten der Leichname tanzen an Pickmans Fingerspitzen, unwillig, sich zähmen zu lassen, und wirbeln wild über die Leinwand. \n Gewöhnliche Maler skizzieren die Erscheinung der Realität, während wahre Künstler das Wahnsinnige auskosten und all die unbekannten Freuden, Schmerzen, Begierden und das Hässliche umreißen."
  },
  Skill_98985_Desc_0 = {
    Text = "<EmbryoFusionIconKeywords:Embryofusion>+ [Arg1], entfernt den <EmptinessKeywords: Leere>-Zustand. <FaxianKeywords:Entdecken> 3 <Chuanggouzaowu:Bemalte Silberreliquien> und wähle eine aus, diese Reliquie hält [Arg2] Runden an."
  },
  Skill_98985_Desc_2 = {
    Text = "<EmbryoFusionIconKeywords:Embryofusion>+ [Arg1], entfernt den <EmptinessKeywords: Leere>-Zustand. <FaxianKeywords:Entdecken> 3 <Chuanggouzaowu:Bemalte Goldreliquien> und wähle eine aus, diese Reliquie hält [Arg2] Runden an."
  },
