  Skill_98989_AwakerSkillBackgroundStory = {
    Text = "Der stille, tiefgründige Friedhof, auf dem die Leichen wie Skulpturen ausgestellt sind, wird zu einer besonderen Art von Modell, das mit der Stille und dem Geheimnis des Todes die endlose Inspiration des Malers weckt. \n Starre Haltungen, blasse Haut, verzerrte Gesichtsausdrücke... Pickman sucht im Schatten und Verfall nach der Möglichkeit der Schönheit."
  },
  Skill_98989_Desc_0 = {
    Text = "Pickman erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Erhalte 1 Stapelung <Kuangxiang:Aliemus-Fantasie>. Für jede Stapelung <Chuangyi:Kreativität>, die Pickman erhält, <EmbryoFusionIconKeywords:Embryofusion>+ [Arg2]."
  },
  Skill_98989_Desc_15 = {
    Text = "Pickman erhält <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Erwecken>: Erhalte 1 Stapelung <Kuangxiang:Fantasia>. Für jede Stapelung <Chuangyi:Kreativität>, die Pickman erhält, <EmbryoFusionIconKeywords:Embryofusion>+ [Arg2]. Die Dauer der Bemalten Goldreliquie, die durch „Abbildung der Schatten \" erzeugt wird, erhöht sich von 1 Runde auf 2 Runden."
