  Skill_98990_AwakerSkillBackgroundStory = {
    Text = "Hast du jemals die wahre Farbe gesehen? \n Es sind nicht sanfte Farben, sondern aggressive, ins Mark eindringende Wahnsinn. \n Jeder Farbstrich bringt einen schmerzhaften Schauer und ekstatische Freude mit sich, das ist die wahre Schönheit, nach der der Maler strebt."
  },
  Skill_98990_BattleDesc = {
    Text = "Verursacht allen Feinden <Damage:[Damage:Arg1]> Punkte garantiert kritischen Schaden [Arg3] Mal, senkt bei jedem Schadenstreffer vorübergehend die Stärke des Ziels um [Exhaustion:Arg2] Punkte <ExhaustionIconKeywords:Stärke> und erhält [Power:Arg2] Punkte <PowerIconKeywords:Temporäre STR>. Für jede in dieser Runde ausgelöste <FaxianKeywords:Entdecken>-Wirkung werden die Basis-Arithmetica-Kosten dieser Karte um 1 gesenkt. Falls „Inspirationsschub!\" ausgelöst wurde, werden 2 zusätzliche Schadenstreffer verursacht."
  },
  Skill_98990_Desc = {
    Text = "Verursacht allen Feinden <Damage:[Damage:Arg1]> Punkte garantiert kritischen Schaden [Arg3] Mal, <TouquKeywords:stiehlt> dem Ziel bei jedem Schadenstreffer [Arg2] Punkte <PowerIconKeywords:Stärke>. Für jede in dieser Runde ausgelöste <FaxianKeywords:Entdecken>-Wirkung werden die Basis-Arithmetica-Kosten dieser Karte um 1 gesenkt. Falls „Inspirationsschub!\" ausgelöst wurde, werden 2 zusätzliche Schadenstreffer verursacht."
